(window.APUSH_TOPICS=window.APUSH_TOPICS||{})[8]=[{"id": "p8-001", "period": 8, "topic_en": "George F. Kennan and the Containment Policy (Long Telegram)", "topic_zh": "凯南与遏制政策（长电报）", "year": 1946, "year_text": "February 1946", "who": ["George F. Kennan"], "who_zh": ["乔治·F·凯南"], "what_en": "In February 1946, American diplomat George F. Kennan sent an 8,000-word cable, the Long Telegram, from the U.S. embassy in Moscow, calling the Soviet Union an Oriental despotism bent on expansion. A year later he published a Foreign Affairs article urging long-term, patient but firm and vigilant containment of Russian expansive tendencies.", "what_zh": "1946年2月，美国驻苏使馆外交官乔治·F·凯南发出8000字的“长电报”，称苏联是“东方专制”国家、扩张野心不止。一年后他在《外交》杂志发文，呼吁对苏联的扩张倾向实行“长期、耐心但坚定而警惕的遏制”。", "cause_en": "Truman and his advisors were alarmed by Soviet pressure on Iran and Turkey, the civil war in Greece, and the growing strength of Communist parties in France and Italy during the postwar privation of 1946 to 1947.", "cause_zh": "1946—1947年，苏联对伊朗和土耳其施压、希腊内战、法意共产党在战后贫困中壮大，使杜鲁门及其顾问深感不安。", "sig_en": "The word containment came to define America's Cold War strategy for decades, shaping the Truman Doctrine, the Marshall Plan, and later military commitments around the world.", "sig_zh": "“遏制”一词此后几十年定义了美国的冷战战略，塑造了杜鲁门主义、马歇尔计划以及后来遍布全球的军事承诺。", "why_term": "containment", "why_term_q": "凯南在“长电报”中提出的对苏战略核心概念是 ______。", "exp_en": "Kennan argued the Soviet system was despotic and expansionist but would eventually collapse if the West opposed it everywhere with patient counter-force. His containment doctrine replaced wartime cooperation with a strategy of limiting Soviet influence.", "exp_zh": "凯南认为苏联体制专制且具扩张性，但只要西方处处以耐心反制加以阻挡，它终将崩溃。遏制主义取代了战时合作，成为限制苏联影响力的战略。", "page": 808, "img": {"file": "img:f2_1323", "credit": "图源：Henretta《America's History》第8版 p.808"}}, {"id": "p8-002", "period": 8, "topic_en": "Truman Doctrine", "topic_zh": "杜鲁门主义", "year": 1947, "year_text": "March 12, 1947", "who": ["Harry S. Truman"], "who_zh": ["哈里·S·杜鲁门"], "what_en": "On March 12, 1947, President Truman told Congress the United States must support free peoples resisting subjugation, and asked for 300 million dollars in aid to Greece and 100 million dollars to Turkey, then facing communist pressure.", "what_zh": "1947年3月12日，杜鲁门总统向国会宣布美国必须支持反抗征服的自由人民，并要求向希腊提供3亿美元、向土耳其提供1亿美元援助，两国当时正面临共产主义压力。", "cause_en": "In February 1947 Britain told Truman it could no longer afford to support the anticommunists in the Greek civil war, and Truman feared a communist victory would bring Soviet domination of the eastern Mediterranean.", "cause_zh": "1947年2月，英国告知杜鲁门无力再支持希腊内战中的反共力量，杜鲁门担心共产党获胜将使苏联主导东地中海。", "sig_en": "The Truman Doctrine announced an open-ended American commitment to anticommunist forces worldwide, moving containment from economic aid toward a global military stance.", "sig_zh": "杜鲁门主义宣告了美国对全球反共力量的开放性承诺，标志遏制政策从经济援助转向全球军事姿态。", "exp_en": "By pledging aid to Greece and Turkey, Truman framed the Cold War as a choice between free institutions and totalitarian regimes, committing the United States to intervene wherever communism threatened.", "exp_zh": "通过承诺援助希腊和土耳其，杜鲁门把冷战框定为自由制度与极权体制之间的抉择，使美国承诺在共产主义威胁出现之处进行干预。", "page": 809, "src": {"text": "I believe that it must be the policy of the United States to support free peoples who are resisting attempted subjugation by armed minorities or by outside pressures.", "attr": "President Harry S. Truman, address before joint session of Congress, March 12, 1947"}}, {"id": "p8-003", "period": 8, "topic_en": "Marshall Plan (European Recovery Program)", "topic_zh": "马歇尔计划（欧洲复兴计划）", "year": 1948, "year_text": "1948 (proposed June 1947)", "who": ["George C. Marshall"], "who_zh": ["乔治·C·马歇尔"], "what_en": "Secretary of State George C. Marshall proposed a massive infusion of American capital to rebuild Europe in a June 1947 Harvard commencement speech. After the communist coup in Czechoslovakia in February 1948 broke the congressional stalemate, Congress approved the plan, and the United States contributed nearly 13 billion dollars over four years.", "what_zh": "国务卿乔治·C·马歇尔在1947年6月哈佛毕业典礼演讲中提议大规模注资重建欧洲。1948年2月捷克斯洛伐克共产党政变打破国会僵局，国会批准该计划，美国四年间出资近130亿美元。", "cause_en": "Europe was sliding into economic chaos in 1947, with starvation and collapsed markets, and Washington feared both a global depression and Communist gains among dispirited Western Europeans.", "cause_zh": "1947年欧洲陷入经济混乱，饥荒与市场崩溃，华盛顿既怕全球萧条重演，又怕心灰意冷的西欧人倒向共产党。", "sig_en": "The plan was highly successful: European industrial production rose 64 percent, Communist appeal waned in the West, and markets for American goods grew stronger, though it also intensified Cold War tensions after Stalin refused to participate.", "sig_zh": "该计划极为成功：欧洲工业生产增长64%，共产党在西欧吸引力下降，美国商品市场扩大；但斯大林拒绝参加后，冷战对峙也随之加剧。", "exp_en": "The Marshall Plan tied European recovery to American aid and trade, making Western Europe prosperous and anticommunist while drawing a sharper line between East and West.", "exp_zh": "马歇尔计划把欧洲复兴与美国援助、贸易绑定，使西欧繁荣且反共，同时让东西方分界更加分明。", "page": 809}, {"id": "p8-004", "period": 8, "topic_en": "Berlin Blockade and Airlift", "topic_zh": "柏林封锁与空运", "year": 1948, "year_text": "June 1948 - May 12, 1949", "who": ["Harry S. Truman", "Joseph Stalin"], "who_zh": ["哈里·S·杜鲁门", "约瑟夫·斯大林"], "what_en": "In June 1948 Stalin blockaded all surface traffic to West Berlin after the Western allies moved toward an independent West German republic. Truman refused to yield, saying the United States would stay, and American and British pilots flew 2.5 million tons of food and fuel into the city over the next year until Stalin lifted the blockade on May 12, 1949.", "what_zh": "1948年6月，西方盟国着手建立独立的西德共和国后，斯大林封锁了通往西柏林的一切陆路交通。杜鲁门拒绝让步，表示美国将坚守，美英飞行员在接下来一年向该市空运了250万吨食品和燃料，直至1949年5月12日斯大林解除封锁。", "cause_en": "The Western allies had consolidated their three occupation zones in 1947 and planned a federal German republic, with Marshall Plan funds meant to make West Berlin a capitalist showplace deep inside the Soviet zone.", "cause_zh": "西方盟国1947年合并三个占领区并计划建立联邦德国，还想用马歇尔计划资金把西柏林打造成苏占区深处的资本主义橱窗。", "sig_en": "The crisis was the closest the two sides came to actual war until the Cuban missile crisis in 1962, made West Berlin a symbol of resistance to communism, and persuaded Western Europe to form NATO.", "sig_zh": "这是1962年古巴导弹危机前美苏最接近热战的一次，使西柏林成为反共象征，并促使西欧组建北约。", "exp_en": "The airlift proved American resolve without firing a shot: Stalin backed down, Germany stayed divided, and the confrontation locked in the Cold War division of Europe.", "exp_zh": "空运以不发一弹的方式证明了美国的决心：斯大林退让，德国维持分裂，这场对峙锁定了欧洲的冷战格局。", "page": 812, "img": {"file": "img:f2_1334", "credit": "图源：Henretta《America's History》第8版 p.812"}}, {"id": "p8-005", "period": 8, "topic_en": "NATO and the Warsaw Pact", "topic_zh": "北约与华约", "year": 1949, "year_text": "April 1949 (Warsaw Pact 1955)", "who": ["United States", "Soviet Union"], "who_zh": ["美国", "苏联"], "what_en": "In April 1949 the United States entered its first peacetime military alliance, the North Atlantic Treaty Organization, as twelve nations agreed that an armed attack against one or more of them in Europe or North America shall be considered an attack against them all. West Germany joined NATO in 1955, and the Soviet Union answered with the Warsaw Pact, a military alliance of eight Eastern European states.", "what_zh": "1949年4月，美国加入其首个和平时期的军事同盟——北大西洋公约组织，十二个成员国约定：对其中一国或多国的武装攻击即视为对全体成员的攻击。1955年西德加入北约，苏联则以由八个东欧国家组成的华沙条约组织回应。", "cause_en": "The Berlin crisis convinced Western European nations to forge a collective security pact with the United States against Soviet pressure.", "cause_zh": "柏林危机促使西欧国家与美国缔结集体安全条约，共同应对苏联压力。", "sig_en": "The rival alliances institutionalized the Cold War, dividing Europe into two armed camps and binding American power permanently to European defense.", "sig_zh": "两大对立同盟使冷战制度化，欧洲分裂为两大军事阵营，美国力量从此与欧洲防务永久绑定。", "exp_en": "NATO turned containment into a formal military commitment, and the Warsaw Pact mirrored it in the East, so that by the mid-1950s Europe was stabilized into two rival blocs.", "exp_zh": "北约把遏制变成了正式军事承诺，华约在东方与之对应，到1950年代中期欧洲稳定为两大对立阵营。", "page": 812, "img": {"file": "img:f2_1334", "credit": "图源：Henretta《America's History》第8版 p.812"}}, {"id": "p8-006", "period": 8, "topic_en": "Founding of the People's Republic of China", "topic_zh": "中华人民共和国成立", "year": 1949, "year_text": "October 1, 1949", "who": ["Mao Zedong", "Jiang Jieshi"], "who_zh": ["毛泽东", "蒋介石"], "what_en": "Mao Zedong's Communists won the Chinese civil war, and the People's Republic of China was formally established on October 1, 1949, while Jiang Jieshi's Nationalists fled to Taiwan. Between 1945 and 1949 the United States had given Jiang 2 billion dollars, but Truman cut off aid rather than intervene militarily.", "what_zh": "毛泽东领导的共产党赢得中国内战，中华人民共和国于1949年10月1日正式成立，蒋介石的国民党退往台湾。1945—1949年美国曾向蒋提供20亿美元，但杜鲁门不愿军事干预而切断援助。", "cause_en": "Truman reasoned that saving Jiang would require direct American military intervention, which he was unwilling to undertake, and Mao then aligned himself with the Soviet Union.", "cause_zh": "杜鲁门认为挽救蒋政权需要美国直接军事干预，而他不愿为之，毛泽东随后与苏联结盟。", "sig_en": "Many Americans read Mao's victory as an American defeat; the pro-Nationalist China lobby blamed the State Department for the loss of China, the United States refused to recognize Red China, and the shock fueled the domestic Red Scare.", "sig_zh": "许多美国人把毛泽东的胜利视为美国的失败；亲国民党的“中国游说团”指责国务院“丢失”中国，美国拒绝承认红色中国，这一冲击助长了国内的红色恐慌。", "exp_en": "The loss of China extended containment to Asia, convinced Washington that communism was on the march, and made Asia the next front of the Cold War.", "exp_zh": "“丢失中国”把遏制延伸到亚洲，使华盛顿认定共产主义正在扩张，亚洲成为冷战的下一个前线。", "page": 814}, {"id": "p8-007", "period": 8, "topic_en": "Korean War", "topic_zh": "朝鲜战争", "year": 1950, "year_text": "June 25, 1950 - July 1953", "who": ["Harry S. Truman", "Douglas MacArthur", "Kim Il Sung", "Syngman Rhee"], "who_zh": ["哈里·S·杜鲁门", "道格拉斯·麦克阿瑟", "金日成", "李承晚"], "what_en": "On June 25, 1950, North Korea attacked across the 38th parallel. Truman won UN authorization for a police action while the Soviet Union was boycotting the Security Council, and an American-led UN force under Douglas MacArthur landed at Inchon, pushed to the Yalu River, and was driven back by massive Chinese intervention. After stalemate, an armistice in July 1953 left Korea divided at the original line; more than 36,000 Americans and 900,000 Koreans died.", "what_zh": "1950年6月25日，朝鲜越过三八线进攻韩国。趁苏联抵制安理会之机，杜鲁门获得联合国“警察行动”授权，麦克阿瑟指挥的美军为首的联合国军在仁川登陆、推进至鸭绿江，又被中国大规模介入打退。僵持之后，1953年7月停战，朝鲜半岛仍以原分界线分裂；美军阵亡逾3.6万人，朝鲜人死亡逾90万。", "cause_en": "Kim Il Sung pressed Stalin until the Soviet leader relented in the spring of 1950, and Truman treated the invasion as a test of the collective security system that could not go unanswered.", "cause_zh": "金日成一再敦促，斯大林1950年春终于松口；杜鲁门把这次入侵视为对集体安全体系的考验，不能不作回应。", "sig_en": "It was the first major proxy battle of the Cold War; it set the precedent for undeclared wars, fixed ground rules by refusing to use atomic bombs, turned containment into a truly global policy, and drove defense spending from 13 billion dollars in 1950 to 50 billion in 1953.", "sig_zh": "这是冷战第一次重大代理人战争：开创了不宣而战的先例，以拒绝使用原子弹定下冷战交战规则，使遏制成为真正的全球政策，并推动军费从1950年的130亿美元增至1953年的500亿美元。", "exp_en": "Korea militarized containment: Truman fired MacArthur on April 11, 1951, for defying limited-war policy, and the war's cost ended Truman's resistance to the NSC-68 military buildup.", "exp_zh": "朝鲜战争使遏制军事化：杜鲁门1951年4月11日因麦克阿瑟违抗有限战争政策将其解职，战争开支也终结了杜鲁门对NSC-68军备扩张的抵制。", "page": 815, "img": {"file": "img:f2_1341", "credit": "图源：Henretta《America's History》第8版 p.815"}}, {"id": "p8-008", "period": 8, "topic_en": "NSC-68", "topic_zh": "NSC-68号文件", "year": 1950, "year_text": "April 1950", "who": ["U.S. National Security Council"], "who_zh": ["美国国家安全委员会"], "what_en": "After the Soviet Union detonated an atomic bomb in September 1949, the National Security Council delivered its report NSC-68 in April 1950, describing the USSR as driven by a fanatic faith seeking domination of the Eurasian landmass and proposing a bold and massive program of rebuilding the West's defensive potential, including the hydrogen bomb, larger conventional forces, and higher taxes.", "what_zh": "苏联1949年9月试爆原子弹后，国家安全委员会于1950年4月提交NSC-68报告，称苏联受“狂热信仰”驱使、谋求主宰欧亚大陆，提议“大胆而宏大的重建西方防务”计划，包括研制氢弹、扩充常规军力、加税。", "cause_en": "America's brief tenure as the sole nuclear power had ended, and Truman asked the NSC, created by the National Security Act of 1947, for a strategic reassessment.", "cause_zh": "美国短暂的核垄断地位终结，杜鲁门要求1947年《国家安全法》设立的国安会进行战略再评估。", "sig_en": "Historians see NSC-68 as having militarized the American approach to the Cold War, which until then had relied largely on economic measures; Truman resisted the buildup until the Korean War reversed him.", "sig_zh": "历史学家认为NSC-68使美国冷战方针军事化，此前主要依赖经济手段；杜鲁门起初抵制扩军，朝鲜战争使他转变立场。", "exp_en": "NSC-68 moved containment beyond Kennan's political and economic tools toward a permanent, expensive military posture funded by higher taxes and national sacrifice.", "exp_zh": "NSC-68把遏制从凯南的政治经济手段推向以加税和国民牺牲为代价的永久性高成本军事姿态。", "page": 813, "img": {"file": "img:f2_1336", "credit": "图源：Henretta《America's History》第8版 p.813"}}, {"id": "p8-009", "period": 8, "topic_en": "Second Red Scare: HUAC and McCarthyism", "topic_zh": "第二次红色恐慌：众议院非美活动调查委员会与麦卡锡主义", "year": 1950, "year_text": "1947-1954", "who": ["Joseph McCarthy", "House Un-American Activities Committee"], "who_zh": ["约瑟夫·麦卡锡", "众议院非美活动调查委员会"], "what_en": "The House Un-American Activities Committee, launched in 1938, sparked the Red Scare with 1947 hearings on Communist infiltration of the movie industry: the Hollywood Ten went to jail for contempt and a blacklist kept hundreds from work. In February 1950 Senator Joseph McCarthy claimed in Wheeling, West Virginia, to hold a list of 205 Communists in the State Department, though he never produced proof. Televised Army-McCarthy hearings in 1954 exposed his tactics, and the Senate censured him 67 to 22 in December 1954; he died in 1957 at forty-eight.", "what_zh": "1938年成立的众议院非美活动调查委员会以1947年电影业共产党渗透听证会点燃红色恐慌：“好莱坞十人”因藐视国会入狱，黑名单使数百人失业。1950年2月，参议员约瑟夫·麦卡锡在西弗吉尼亚州惠灵宣称手握国务院205名共产党人名单，却从未拿出证据。1954年电视直播的陆军—麦卡锡听证会暴露其手段，参议院同年12月以67比22谴责他；他1957年去世，年仅48岁。", "cause_en": "Truman's 1947 Loyalty-Security Program legitimized hunting disloyalty, and the Hiss case, the Rosenberg espionage trial, the loss of China, and the Korean War gave anticommunist charges credibility.", "cause_zh": "杜鲁门1947年忠诚—安全计划使“清查不忠”合法化，希斯案、罗森伯格间谍案、“丢失中国”和朝鲜战争都为反共指控增添了可信度。", "sig_en": "The era attached McCarthy's name to political repression: charges almost always targeted Democrats, civil liberties suffered, and only television exposure of his bullying finally broke his power.", "sig_zh": "这个时代以麦卡锡之名行政治压迫之实：指控几乎全针对民主党人，公民自由受损，直到电视曝光其霸凌手段才终结其权势。", "exp_en": "McCarthyism showed how Cold War fear could be weaponized at home: unproven accusations ruined careers, while real espionage cases like those of Hiss and the Rosenbergs lent the hysteria a veneer of legitimacy.", "exp_zh": "麦卡锡主义表明冷战恐惧如何在国内被武器化：未经证实的指控毁掉职业生涯，而希斯案、罗森伯格案等真实间谍案又为这场歇斯底里披上合法外衣。", "page": 821, "src": {"text": "Today we are engaged in a final, all-out battle between communistic atheism and Christianity.", "attr": "Senator Joseph McCarthy, speech in Wheeling, West Virginia, February 9, 1950"}}, {"id": "p8-010", "period": 8, "topic_en": "New Look and Massive Retaliation", "topic_zh": "“新面貌”政策与大规模报复战略", "year": 1953, "year_text": "1953", "who": ["Dwight D. Eisenhower", "John Foster Dulles"], "who_zh": ["德怀特·D·艾森豪威尔", "约翰·福斯特·杜勒斯"], "what_en": "To limit the cost of containment, Eisenhower adopted the New Look defense policy: rely on the nuclear arsenal and deemphasize expensive conventional forces, stepping up hydrogen bomb production and long-range bombing capabilities. Secretary of State Dulles dubbed the deterrent massive retaliation, the threat of an all-out American nuclear response to Soviet aggression.", "what_zh": "为控制遏制成本，艾森豪威尔推行“新面貌”防务政策：依靠核武库、弱化昂贵的常规军力，加速氢弹生产和远程轰炸能力。国务卿杜勒斯把这种威慑命名为“大规模报复”，即以美国全面核反击威胁苏联侵略。", "cause_en": "With no end to the Cold War in sight, Eisenhower wanted to economize on defense while still deterring the Soviet Union.", "cause_zh": "冷战看不到尽头，艾森豪威尔想在继续威慑苏联的同时节约防务开支。", "sig_en": "The arms race became a central feature of the Cold War: the Soviets matched the United States weapon for weapon, and both nations had intercontinental ballistic missiles by 1958.", "sig_zh": "军备竞赛成为冷战的核心特征：苏联以牙还牙，到1958年两国都拥有洲际弹道导弹。", "why_term": "massive retaliation", "why_term_q": "杜勒斯提出的以全面核反击威慑苏联侵略的战略被称为 ______。", "exp_en": "The New Look substituted nuclear threats for costly ground forces, making deterrence cheaper but raising the stakes of any confrontation to nuclear war.", "exp_zh": "“新面貌”以核威胁替代昂贵的地面部队，使威慑更便宜，却把任何对峙的赌注抬高到核战争级别。", "page": 826}, {"id": "p8-011", "period": 8, "topic_en": "Sputnik and the Space Race", "topic_zh": "人造卫星与太空竞赛", "year": 1957, "year_text": "1957", "who": ["Soviet Union"], "who_zh": ["苏联"], "what_en": "The Soviet Union beat the United States into space with the 1957 Sputnik satellite, followed by cosmonaut Yuri Gagarin's flight in 1961. In a 1962 speech Kennedy committed the nation to landing a man on the moon within the decade, persuaded Congress to increase NASA funding, and American astronauts reached the moon in 1969.", "what_zh": "苏联以1957年“人造卫星”号抢先进入太空，1961年加加林又完成载人飞行。肯尼迪在1962年演讲中承诺十年内把人送上月球，说服国会增加NASA拨款，美国宇航员1969年登月。", "cause_en": "Spaceflight became a Cold War contest for prestige and technological supremacy after the Soviets demonstrated superior rockets.", "cause_zh": "苏联展示出更强的火箭技术后，太空飞行成为冷战中争夺威望与技术霸权的竞赛。", "sig_en": "The shock spurred American investment in science and technology, including the National Defense Education Act of 1958, and turned space into a central Cold War battleground.", "sig_zh": "这一冲击促使美国大举投资科学与技术，包括1958年《国防教育法》，太空成为冷战的核心战场。", "exp_en": "Sputnik turned a scientific achievement into a political crisis: falling behind in space meant, in American eyes, falling behind in the Cold War itself.", "exp_zh": "“人造卫星”把一项科学成就变成政治危机：在美国人眼中，太空落后就意味着在冷战本身中落后。", "page": 832, "img": {"file": "img:f2_1392", "credit": "图源：Henretta《America's History》第8版 p.832"}}, {"id": "p8-012", "period": 8, "topic_en": "Bay of Pigs Invasion and Cuban Missile Crisis", "topic_zh": "猪湾入侵与古巴导弹危机", "year": 1961, "year_text": "April 1961; October 1962", "who": ["John F. Kennedy", "Fidel Castro", "Nikita Khrushchev"], "who_zh": ["约翰·F·肯尼迪", "菲德尔·卡斯特罗", "尼基塔·赫鲁晓夫"], "what_en": "After Fidel Castro overthrew Batista in 1959, Kennedy carried out an Eisenhower-era plan: on April 17, 1961, 1,400 CIA-trained Cuban exiles landed at the Bay of Pigs and were crushed by Castro's troops. In October 1962, U.S. reconnaissance found Soviet missile bases in Cuba; Kennedy announced a naval quarantine on October 22, Soviet ships turned back on October 25, and a deal followed: Kennedy pledged not to invade Cuba and Khrushchev dismantled the missiles, while Kennedy secretly removed U.S. missiles from Turkey.", "what_zh": "1959年卡斯特罗推翻巴蒂斯塔后，肯尼迪执行了艾森豪威尔时期的计划：1961年4月17日，1400名中情局训练的古巴流亡者在猪湾登陆，被卡斯特罗军队击溃。1962年10月，美国侦察机发现苏联在古巴的导弹基地；肯尼迪10月22日宣布海上“隔离”，10月25日苏联船只返航，随后达成协议：肯尼迪承诺不入侵古巴，赫鲁晓夫拆除导弹，肯尼迪则秘密从土耳其撤走美国导弹。", "cause_en": "Kennedy was determined to keep Cuba out of the Soviet orbit and took Khrushchev's 1961 pledge to support wars of national liberation as a direct challenge.", "cause_zh": "肯尼迪决心不让古巴落入苏联轨道，并把赫鲁晓夫1961年支持“民族解放战争”的宣言视为直接挑战。", "sig_en": "The risk of nuclear war was greater than at any other time in the Cold War; the brush with the edge chastened both sides and prompted a slight thaw in U.S.-Soviet relations.", "sig_zh": "核战争风险达到冷战史最高点；这次与悬崖擦肩而过的经历使双方都有所收敛，美苏关系出现轻微缓和。", "exp_en": "The two Cuba crises bookended Kennedy's Cold War education: a botched covert invasion taught the limits of force, and the missile crisis showed how close brinksmanship could come to catastrophe.", "exp_zh": "两次古巴危机是肯尼迪冷战教育的首尾：失败的秘密入侵暴露了武力的局限，导弹危机则表明边缘政策离灾难有多近。", "page": 830, "img": {"file": "img:f2_1386", "credit": "图源：Henretta《America's History》第8版 p.830"}}, {"id": "p8-013", "period": 8, "topic_en": "Bretton Woods System: World Bank and IMF", "topic_zh": "布雷顿森林体系：世界银行与国际货币基金组织", "year": 1944, "year_text": "July 1944", "who": ["United States"], "who_zh": ["美国"], "what_en": "At the July 1944 Bretton Woods, New Hampshire conference, the World Bank was created to provide loans for reconstructing war-torn Europe and developing former colonies, and the International Monetary Fund was set up to stabilize currencies and provide a predictable monetary environment, with the U.S. dollar as the benchmark. Joined in 1947 by the General Agreement on Tariffs and Trade, they guided the postwar global economy.", "what_zh": "1944年7月新罕布什尔州布雷顿森林会议创立了世界银行（为重建战后欧洲和发展前殖民地提供贷款）和国际货币基金组织（稳定货币、提供可预期的货币环境，以美元为基准）。1947年《关税与贸易总协定》加入后，它们共同主导了战后全球经济。", "cause_en": "American global supremacy and the desire for an open-market world economy required stable currencies and institutions to channel American capital abroad.", "cause_zh": "美国的全球经济霸权和建立开放市场世界经济的愿望，需要稳定的货币与机构来向海外输送美国资本。", "sig_en": "The system made American capital available cheaply to nations adopting free-trade capitalist economies, though critics rightly charged that it favored the United States and let Washington dictate lending terms.", "sig_zh": "该体系以低廉条件向实行自由贸易资本主义的国家提供美国资本，但批评者指出它偏袒美国、让华盛顿主导贷款条件。", "exp_en": "Bretton Woods was the economic counterpart of containment: an American-led order that tied prosperity to free markets and the dollar.", "exp_zh": "布雷顿森林体系是遏制的经济版：以美国为首、把繁荣与自由市场和美元绑定的秩序。", "page": 840, "img": {"file": "img:f2_1411", "credit": "图源：Henretta《America's History》第8版 p.840"}}, {"id": "p8-014", "period": 8, "topic_en": "GI Bill (Servicemen's Readjustment Act)", "topic_zh": "《退伍军人权利法案》（GI法案）", "year": 1944, "year_text": "1944", "who": ["U.S. veterans"], "who_zh": ["美国退伍军人"], "what_en": "The Servicemen's Readjustment Act of 1944, known as the GI Bill, put veterans through school on the government's dime: by the mid-1950s, 2.2 million veterans had attended college and 5.6 million trade school, training nearly half a million engineers. Between World War II and 1966, one of every five new single-family homes, 2.5 million in all, was financed through a GI Bill mortgage.", "what_zh": "1944年《退伍军人权利法案》（GI法案）让退伍军人公费上学：到1950年代中期，220万退伍军人上过大学、560万人上过技校，培养出近50万工程师。二战结束到1966年间，每五栋新建独户住宅就有一栋（共250万栋）靠GI法案贷款建成。", "cause_en": "The nation sought to reward returning servicemen and ease their transition to civilian life with education and affordable homeownership.", "cause_zh": "国家希望以教育和可负担的住房回报归国军人，帮助他们回归平民生活。", "sig_en": "The GI Bill made middle-class status more accessible than ever, gave the United States the best-educated workforce in the world, and drove the consumer spending behind the postwar boom; one observer called it the most important educational and social transformation in American history.", "sig_zh": "GI法案让中产地位空前可及，使美国拥有世界受教育程度最高的劳动力，并推动了战后繁荣背后的消费支出；一位观察家称之为“美国历史上最重要的教育与社会变革”。", "exp_en": "By funding degrees and mortgages, the GI Bill converted millions of veterans into college graduates and homeowners, the twin pillars of the new middle class.", "exp_zh": "GI法案以学位和房贷把数百万退伍军人变成大学毕业生和房主——新中产阶级的两大支柱。", "page": 844, "img": {"file": "img:f2_1421", "credit": "图源：Henretta《America's History》第8版 p.844"}}, {"id": "p8-015", "period": 8, "topic_en": "Kitchen Debate and Consumer Culture", "topic_zh": "厨房辩论与消费文化", "year": 1959, "year_text": "1959", "who": ["Richard Nixon", "Nikita Khrushchev"], "who_zh": ["理查德·尼克松", "尼基塔·赫鲁晓夫"], "what_en": "At the 1959 American National Exhibition in Moscow, Vice President Richard Nixon and Soviet premier Nikita Khrushchev strolled through a model American home and debated the merits of Pepsi-Cola, TV dinners, and electric ovens. Nixon insisted that a modern home full of consumer goods was within reach of the average worker, telling Khrushchev that any steelworker could buy this house.", "what_zh": "1959年莫斯科美国国家展览会上，副总统理查德·尼克松与苏联领导人尼基塔·赫鲁晓夫漫步一座美式样板房，为百事可乐、电视晚餐、电烤箱等消费品的优劣展开辩论。尼克松坚称普通工人也买得起这样塞满消费品的现代住宅，对赫鲁晓夫说“任何钢铁工人都买得起这栋房子”。", "cause_en": "It was Cold War politics by other means: a symbolic contest over which country's standard of living was higher, with Nixon conceding Soviet rockets but claiming American superiority in color television and home appliances.", "cause_zh": "这是冷战政治的另一种形式：两国生活水平的象征性较量——尼克松承认苏联火箭更强，但宣称美国在彩电和家电上领先。", "sig_en": "The debate revealed how Americans saw themselves by the late 1950s: as homeowners and consumers, for whom the middle-class American Dream was a commercial aspiration.", "sig_zh": "这场辩论揭示了1950年代末美国人的自我认知：房主与消费者，中产阶级美国梦是一种商业抱负。", "exp_en": "Consumer abundance became an ideological weapon: the kitchen, not the missile silo, was Nixon's proof that the American system worked.", "exp_zh": "消费丰裕成了意识形态武器：尼克松用厨房而非导弹发射井来证明美国制度的优越。", "page": 838, "src": {"text": "Any steelworker could buy this house.", "attr": "Vice President Richard Nixon to Soviet premier Nikita Khrushchev, American National Exhibition, Moscow, 1959"}}, {"id": "p8-016", "period": 8, "topic_en": "Rise of Television", "topic_zh": "电视的兴起", "year": 1948, "year_text": "1947-1960", "who": ["CBS", "NBC"], "who_zh": ["哥伦比亚广播公司", "全国广播公司"], "what_en": "Commercial television spread with stunning speed: 7,000 TV sets stood in American homes in 1947, CBS and NBC began regular programming in 1948, Americans owned 7.3 million sets by 1950, and ten years later 87 percent of homes had at least one set. Television became the principal mediator between the consumer and the marketplace, as advertisers mastered the art of manufacturing consumer desire.", "what_zh": "商业电视以惊人速度普及：1947年美国家庭仅有7000台电视机，1948年CBS和NBC开始常规播出，1950年拥有量达730万台，十年后87%的家庭至少有一台。电视成为消费者与市场之间的主要中介，广告商精通了制造消费欲望的艺术。", "cause_en": "Postwar prosperity, network investment in regular programming, and falling set prices put television within reach of the new middle class.", "cause_zh": "战后繁荣、电视网对常规节目的投入以及电视机降价，使新中产阶级买得起电视。", "sig_en": "Only the automobile and the personal computer equaled television in transforming twentieth-century everyday life; it revolutionized advertising and soon shaped politics itself, from the Army-McCarthy hearings to the 1960 debates.", "sig_zh": "在改变20世纪日常生活方面，只有汽车和个人电脑能与电视比肩；它革新了广告业，并很快塑造政治本身——从陆军—麦卡锡听证会到1960年电视辩论。", "exp_en": "Television domesticated the Cold War and consumerism at once: the same box that sold appliances also broadcast McCarthy's downfall and Kennedy's image.", "exp_zh": "电视同时把冷战和消费主义带进客厅：推销家电的同一个盒子，也播出了麦卡锡的垮台和肯尼迪的形象。", "page": 845}, {"id": "p8-017", "period": 8, "topic_en": "Baby Boom and Dr. Spock", "topic_zh": "婴儿潮与斯波克医生", "year": 1957, "year_text": "1946-1964 (peak 1957)", "who": ["Benjamin Spock"], "who_zh": ["本杰明·斯波克"], "what_en": "After a century and a half of decline, the birthrate shot up: more babies were born between 1948 and 1953 than in the previous thirty years, the average marriage age fell to twenty-two for men and twenty for women, and the boom peaked in 1957. Dr. Benjamin Spock's Common Sense Book of Baby and Child Care, published in 1946, sold a million copies a year, urging mothers to abandon the rigid feeding schedules of an earlier generation.", "what_zh": "在下降一个半世纪后，出生率飙升：1948—1953年出生的婴儿超过此前三十年总和，平均婚龄降至男性22岁、女性20岁，婴儿潮1957年达顶峰。本杰明·斯波克医生1946年出版的《育儿常识》每年售出100万册，劝母亲们抛弃上一代僵硬的喂养时间表。", "cause_en": "Stable postwar marriages, younger parents, and the expectation that having several children was part of adulthood, almost a citizen's responsibility, produced the bumper crop.", "cause_zh": "战后婚姻稳定、父母更年轻，以及“多生孩子是成年人的本分、近乎公民责任”的观念，共同造就了生育大年。", "sig_en": "The boom's widening impact rippled through schools, colleges, and the job market for decades, and Spock's mixed messages to mothers helped inspire the resurgence of feminism in the 1960s.", "sig_zh": "婴儿潮的涟漪效应数十年间席卷学校、大学和就业市场；斯波克给母亲们的矛盾信息助推了1960年代女权主义的复兴。", "exp_en": "The baby boom was a demographic anomaly, a temporary reversal of long-term trends that made the 1950s family with three children the era's defining image.", "exp_zh": "婴儿潮是人口学上的反常现象，是长期趋势的暂时逆转，使“三个孩子的1950年代家庭”成为时代的标志性形象。", "page": 851}, {"id": "p8-018", "period": 8, "topic_en": "Levittown and Suburbanization", "topic_zh": "莱维特镇与郊区化", "year": 1947, "year_text": "1947", "who": ["William J. Levitt"], "who_zh": ["威廉·J·莱维特"], "what_en": "Long Island builder William J. Levitt revolutionized housing with mass-production techniques: his basic four-room house with kitchen appliances sold for 7,990 dollars when the first Levittown opened in 1947. Backed by FHA-insured thirty-year mortgages at 5 percent down and VA loans requiring only a token 1 dollar down, homeownership jumped from about 45 percent to 60 percent by 1960.", "what_zh": "长岛建筑商威廉·J·莱维特以流水线技术革新住宅建造：1947年首个莱维特镇开盘时，带厨房电器的基本四居室仅售7990美元。在联邦住房管理局承保的三十年期按揭（首付5%）和退伍军人管理局象征性1美元首付贷款的支持下，住房自有率从约45%跃升至1960年的60%。", "cause_en": "Pent-up housing demand, cheap farmland, mass-production building, and federal mortgage insurance through the FHA and VA put new homes within reach of young families.", "cause_zh": "被压抑的住房需求、廉价农地、流水线建造，以及联邦住房管理局和退伍军人管理局的按揭担保，让年轻家庭买得起新房。", "sig_en": "Suburbs grew homogeneous by age, class, and race: Levitt's houses carried restrictive covenants barring occupancy by members of other than the Caucasian race, and though Shelley v. Kraemer in 1948 outlawed such covenants, FHA and VA redlining kept discrimination alive until the Fair Housing Act of 1968.", "sig_zh": "郊区在年龄、阶级和种族上高度同质：莱维特的房子附带限制性契约，禁止“非白种人”入住；1948年“雪莱诉克雷默案”虽宣布此类契约违宪，但联邦住房管理局和退伍军人管理局的“红线”政策使歧视延续到1968年《公平住房法》。", "exp_en": "Levittown made the suburban single-family home the physical form of the American Dream, while federal policy and private covenants reserved that dream largely for white families.", "exp_zh": "莱维特镇使郊区独户住宅成为美国梦的实体形态，而联邦政策与私人契约把这个梦主要留给了白人家庭。", "page": 857}, {"id": "p8-019", "period": 8, "topic_en": "National Interstate and Defense Highways Act", "topic_zh": "《州际与国防公路法》", "year": 1956, "year_text": "1956", "who": ["Dwight D. Eisenhower"], "who_zh": ["德怀特·D·艾森豪威尔"], "what_en": "In 1956 the National Interstate and Defense Highways Act authorized 26 billion dollars over ten years for a 42,500-mile nationally integrated highway system. Cast as a Cold War necessity because broad highways would ease evacuation of crowded cities in a nuclear attack, it was enthusiastically endorsed by President Eisenhower.", "what_zh": "1956年《州际与国防公路法》授权十年内拨款260亿美元，修建4.25万英里的全国一体化高速公路网。该法以冷战需要为名——宽阔公路便于核攻击时疏散拥挤城市——得到艾森豪威尔总统的热情支持。", "cause_en": "Car ownership tripled from 25 million in 1945 to 75 million by 1965, gas cost 15 cents a gallon, and suburban growth on a massive scale was impossible without automobiles and the roads for them.", "cause_zh": "汽车保有量从1945年的2500万辆增至1965年的750万辆，汽油每加仑15美分；没有汽车和公路，大规模郊区化不可能实现。", "sig_en": "An enormous public works program surpassing anything undertaken during the New Deal, the highways made the massive suburbanization of the 1960s possible, while rerouting traffic away from small towns and cutting wide swaths through old city neighborhoods.", "sig_zh": "这是超越新政时期任何工程的宏大公共工程：高速公路使1960年代的大规模郊区化成为可能，同时把车流从小镇引开，并在老城区划出宽阔的通道。", "exp_en": "The interstate system was Cold War infrastructure with domestic consequences: built to move missiles and evacuees, it ended up moving commuters and reshaping American geography.", "exp_zh": "州际高速网是带有国内后果的冷战基础设施：为运送导弹和疏散人群而建，最终运送的是通勤者，并重塑了美国地理。", "page": 857}, {"id": "p8-020", "period": 8, "topic_en": "Rise of the Sunbelt", "topic_zh": "阳光地带的崛起", "year": null, "year_text": "postwar decades (1940-1970)", "who": ["Sunbelt migrants"], "who_zh": ["阳光地带移民"], "what_en": "Suburban living was most at home in the Sunbelt, the southern and southwestern states, where taxes were low, the climate mild, and open space allowed sprawling subdivisions. Florida added 3.5 million people between 1940 and 1970, Texas profited from petrochemical and defense industries, and by 1970 California held one-tenth of the nation's population and surpassed New York as the most populous state.", "what_zh": "郊区生活在阳光地带——南部和西南部各州——最为兴盛：税低、气候温和、开阔土地容得下蔓延的住宅区。1940—1970年佛罗里达增加350万人口，得克萨斯受益于石化与国防工业，到1970年加州人口占全国十分之一，超过纽约成为人口第一大州。", "cause_en": "Military bases proliferated across the South and Southwest, and government contracts fueled aerospace, defense, and electronics industries centered in Sunbelt metropolitan regions, drawing workers and retirees alike.", "cause_zh": "军事基地遍布南部和西南部，政府合同助推了以阳光地带大都市区为中心的航空航天、国防和电子工业，吸引工人与退休者涌入。", "sig_en": "Sunbelt growth shifted population and political weight southward and westward, and its close relationship with the military-industrial complex gave Sunbelt politicians every reason to support defense spending.", "sig_zh": "阳光地带的增长把人口与政治重心推向南方和西部；它与军工复合体的紧密关系使阳光地带政客有充分理由支持国防开支。", "exp_en": "The Sunbelt was where Cold War spending met suburban sprawl: defense dollars built the jobs, highways, and subdivisions that redrew America's demographic map.", "exp_zh": "阳光地带是冷战开支与郊区蔓延的交汇点：国防美元带来了工作、公路和住宅区，重绘了美国的人口地图。", "page": 862, "img": {"file": "img:f2_1467", "credit": "图源：Henretta《America's History》第8版 p.862"}}, {"id": "p8-021", "period": 8, "topic_en": "Eisenhower Warns of the Military-Industrial Complex", "topic_zh": "艾森豪威尔警告军工复合体", "year": 1961, "year_text": "January 1961", "who": ["Dwight D. Eisenhower"], "who_zh": ["德怀特·D·艾森豪威尔"], "what_en": "In his final address to the nation in 1961, President Dwight D. Eisenhower warned of the power of the military-industrial complex, which by then employed 3.5 million Americans. Military spending had grown from 1 percent of gross domestic product in previous peacetime years to 10 percent, with firms like Boeing, General Dynamics, and Lockheed dependent on Pentagon contracts.", "what_zh": "1961年，德怀特·D·艾森豪威尔总统在告别演说中警告“军工复合体”的权力——它当时雇佣了350万美国人。军费占国内生产总值的比重从以往和平时期的1%升至10%，波音、通用动力、洛克希德等公司依赖五角大楼合同生存。", "cause_en": "The complex had its roots in World War II business-government partnerships, and after 1945 the country lived in nominal peace but permanent military mobilization, with defense industries in long-term relationships with the Pentagon.", "cause_zh": "该复合体根植于二战时期的政商合作；1945年后美国名义上处于和平，实则永久军事动员，国防工业与五角大楼形成长期共生关系。", "sig_en": "Coming from the general who had fostered the defense establishment, the warning named a permanent feature of American life and urged vigilance against its unwarranted influence.", "sig_zh": "警告出自一手扶植国防建制的将军之口，它点名了美国生活的一个永久特征，并呼吁警惕其不当影响。", "why_term": "military-industrial complex", "why_term_q": "艾森豪威尔在告别演说中警告国民警惕 ______ 的不当影响。", "exp_en": "Eisenhower's farewell gave a name to the Cold War economy: a self-perpetuating alliance of the armed forces and defense contractors that thrived even in peacetime.", "exp_zh": "艾森豪威尔的告别演说为冷战经济命名：军队与国防承包商自我延续的联盟，即使在和平时期也欣欣向荣。", "page": 841, "src": {"text": "We must guard against the acquisition of unwarranted influence, whether sought or unsought, by the military-industrial complex.", "attr": "President Dwight D. Eisenhower, farewell address to the nation, 1961"}, "img": {"file": "img:f2_1415", "credit": "图源：Henretta《America's History》第8版 p.841"}}, {"id": "p8-022", "period": 8, "topic_en": "Postwar Religious Revival (Billy Graham)", "topic_zh": "战后宗教复兴（葛培理）", "year": 1949, "year_text": "1949-1960", "who": ["Billy Graham"], "who_zh": ["葛培理"], "what_en": "In an age of anxiety over nuclear annihilation and godless communism, church membership jumped from 49 percent of the population in 1940 to 70 percent in 1960. The young Reverend Billy Graham, making brilliant use of television, radio, and advertising, became the nation's leading evangelical through his massive 1949 Los Angeles revival and 1957 Madison Square Garden crusade.", "what_zh": "在对核毁灭和“无神论共产主义”的焦虑年代，教会成员占人口比例从1940年的49%跃升至1960年的70%。年轻的葛培理牧师娴熟运用电视、广播和广告，凭借1949年洛杉矶大型复兴布道和1957年麦迪逊广场花园布道大会成为全国福音派领袖。", "cause_en": "Americans yearned for a reaffirmation of faith amid Cold War fear, and a new crop of preachers packaged religion for the mass media age.", "cause_zh": "冷战恐惧中美国人渴望重申信仰，新一代布道家把宗教包装成大众传媒时代的产品。", "sig_en": "Rather than clashing with middle-class consumption, the revival meshed with it: preachers like Graham told Americans that moral lives deserved material blessings, and faith became part of Cold War American identity against godless communism.", "sig_zh": "复兴并未与中产消费伦理冲突，反而与之相融：葛培理等布道家告诉美国人，道德的生活配得上物质祝福，信仰成为冷战美国身份的一部分，与“无神论共产主义”相对立。", "exp_en": "The revival shows the 1950s consensus at work: religion, anticommunism, and prosperity reinforced one another in the making of the middle-class mainstream.", "exp_zh": "这场复兴展现了1950年代共识的运作：宗教、反共和繁荣相互强化，共同塑造了中产阶级主流。", "page": 849, "img": {"file": "img:f2_1432", "credit": "图源：Henretta《America's History》第8版 p.849"}}, {"id": "p8-023", "period": 8, "topic_en": "Executive Order 8802", "topic_zh": "8802号行政命令", "year": 1941, "year_text": "June 1941", "who": ["A. Philip Randolph", "Franklin Roosevelt"], "who_zh": ["菲利普·伦道夫", "罗斯福"], "what_en": "Facing A. Philip Randolph's threatened 1941 march on Washington, President Franklin Roosevelt issued Executive Order 8802 in June, prohibiting racial discrimination in defense industries and creating the Fair Employment Practices Commission.", "what_zh": "1941年6月，为阻止伦道夫率十万人向华盛顿进军的计划，罗斯福总统发布8802号行政命令，禁止国防工业中的种族歧视，并设立公平就业实践委员会。", "cause_en": "Randolph's Brotherhood of Sleeping Car Porters demanded equal opportunity in the fast-expanding wartime defense jobs, and Roosevelt issued the order to avoid a divisive protest in the capital.", "cause_zh": "伦道夫的卧铺车厢搬运工兄弟会要求在战时迅速扩张的国防就业中获得平等机会；罗斯福为避免在首都发生分裂性抗议而发布命令。", "sig_en": "The Fair Employment Practices Commission had few enforcement powers, but the order set an important precedent of federal action against discrimination and showed that concerted African American pressure could sway white leaders.", "sig_zh": "公平就业实践委员会执法权有限，但该命令开创了联邦政府反歧视行动的先例，并证明有组织的黑人施压能够左右白人领袖。", "exp_en": "Executive Order 8802 barred racial discrimination in defense industries. Though the FEPC had little enforcement power, the order proved that mass black pressure could force federal action — a lesson the movement would reuse for decades.", "exp_zh": "8802号行政命令禁止国防工业中的种族歧视。公平就业实践委员会虽执法权有限，但该命令证明大规模黑人施压能迫使联邦政府行动——这一经验被民权运动沿用数十年。", "page": 873, "img": {"file": "img:f2_1496", "credit": "图源：Henretta《America's History》第8版 p.873"}}, {"id": "p8-024", "period": 8, "topic_en": "Brown v. Board of Education of Topeka", "topic_zh": "布朗诉托皮卡教育委员会案", "year": 1954, "year_text": "May 17, 1954", "who": ["Thurgood Marshall", "Linda Brown", "Earl Warren"], "who_zh": ["瑟古德·马歇尔", "琳达·布朗", "厄尔·沃伦"], "what_en": "In a unanimous decision on May 17, 1954, the Supreme Court ruled public school segregation unconstitutional, overturning Plessy v. Ferguson's separate-but-equal doctrine; Chief Justice Earl Warren wrote that separate educational facilities are inherently unequal, and Brown II (1955) ordered integration with all deliberate speed.", "what_zh": "1954年5月17日，最高法院一致判决公立学校种族隔离违宪，推翻普莱西案的'隔离但平等'原则；首席大法官厄尔·沃伦写道，隔离的教育设施本身就是不平等的。1955年的布朗案二要求以'一切审慎速度'推进融合。", "cause_en": "NAACP lawyers, led by Thurgood Marshall, had spent decades using the Fourteenth Amendment's equal protection clause to attack segregation, and the case of Linda Brown of Topeka, Kansas, gave the Court the vehicle to decide.", "cause_zh": "以瑟古德·马歇尔为首的NAACP律师团数十年来一直用第十四修正案的平等保护条款挑战隔离，堪萨斯州托皮卡的琳达·布朗案为最高法院作出裁决提供了契机。", "sig_en": "The ruling validated the NAACP's legal strategy, but it triggered massive white resistance — Senator Harry F. Byrd's call for massive resistance and the 1956 Southern Manifesto signed by 101 members of Congress — showing that legal victories alone could not end segregation.", "sig_zh": "判决验证了NAACP的法律战略，但也引发白人'大规模抵抗'——参议员哈里·伯德的抵抗呼吁和101名国会议员签署的1956年《南方宣言》，表明仅靠法律胜利无法终结隔离。", "why_term": "separate but equal", "why_term_q": "1896年普莱西案确立、1954年被布朗案推翻的种族隔离法律原则是 ______。", "exp_en": "Brown overturned the separate-but-equal doctrine in public education, validating the NAACP's long legal strategy. White massive resistance and the Southern Manifesto limited enforcement, showing legal victories alone could not end segregation.", "exp_zh": "布朗案在公立学校领域推翻了'隔离但平等'原则，验证了NAACP长期法律战略的成功。白人的大规模抵抗与《南方宣言》限制了判决执行，表明仅靠法律胜利无法终结隔离。", "page": 878}, {"id": "p8-025", "period": 8, "topic_en": "Emmett Till", "topic_zh": "埃米特·蒂尔谋杀案", "year": 1955, "year_text": "Summer 1955", "who": ["Emmett Till", "Mose Wright"], "who_zh": ["埃米特·蒂尔", "摩西·赖特"], "what_en": "In the summer of 1955, fourteen-year-old Emmett Till of Chicago was tortured and murdered in Mississippi after being seen talking to a white woman in a grocery store; his mutilated body was found tied with barbed wire to a cotton gin fan, and photos in Jet magazine brought the crime national attention.", "what_zh": "1955年夏，14岁的芝加哥少年埃米特·蒂尔在密西西比因被看到在杂货店与白人女子交谈而遭虐杀；他被铁丝捆在轧棉机风扇上的残缺遗体被发现，《Jet》杂志刊登的照片让全国震惊。", "cause_en": "The entrenched white-supremacist culture of Mississippi, where black residents had virtually no political rights and violence enforced racial boundaries, produced the murder.", "cause_zh": "密西西比根深蒂固的白人至上文化——黑人几乎没有政治权利、暴力被用来维护种族界限——酿成了这起谋杀。", "sig_en": "Despite eyewitness testimony by Till's uncle Mose Wright, an all-white jury acquitted the two killers, who later admitted their guilt in Look magazine; this miscarriage of justice galvanized an entire generation of African Americans and helped ignite the direct-action movement.", "sig_zh": "尽管有蒂尔的叔叔摩西·赖特的目击证词，全白人陪审团仍判两名凶手无罪，凶手后来还在《Look》杂志上认罪。这起冤案激起整整一代非裔美国人，为直接行动运动的兴起点燃了火种。", "exp_en": "The 1955 murder of Emmett Till and the acquittal of his killers by an all-white jury — with the killers later confessing in Look magazine — galvanized a generation of African Americans and helped ignite the direct-action movement.", "exp_zh": "1955年蒂尔被谋杀、全白人陪审团判凶手无罪（凶手后在《Look》杂志认罪），激起整整一代非裔美国人，为直接行动运动的兴起埋下火种。", "page": 880, "img": {"file": "img:f2_1517", "credit": "图源：Henretta《America's History》第8版 p.880"}}, {"id": "p8-026", "period": 8, "topic_en": "Montgomery Bus Boycott", "topic_zh": "蒙哥马利公交抵制运动", "year": 1955, "year_text": "December 1955–November 1956", "who": ["Rosa Parks", "Martin Luther King Jr."], "who_zh": ["罗莎·帕克斯", "小马丁·路德·金"], "what_en": "After Rosa Parks was arrested on December 1, 1955 for refusing to give up her bus seat to a white man, Montgomery's African Americans boycotted the bus system for 381 days under the leadership of the Reverend Martin Luther King Jr., until the Supreme Court ruled bus segregation unconstitutional in November 1956.", "what_zh": "1955年12月1日罗莎·帕克斯因拒绝给白人让座被捕后，蒙哥马利的非裔美国人在牧师小马丁·路德·金领导下抵制公交系统381天，直到1956年11月最高法院判决公交隔离违宪。", "cause_en": "Segregated buses humiliated black riders daily, and Parks — a longtime NAACP member of sterling reputation who had been contemplating such an act — provided the right person to challenge the ordinance; earlier boycotts in Harlem (1941) and Baton Rouge (1953) offered models.", "cause_zh": "隔离的公交系统每天羞辱黑人乘客，而长期担任NAACP成员、声誉卓著且早有此意的帕克斯成了挑战该法令的合适人选；哈莱姆（1941）和巴吞鲁日（1953）的早期抵制提供了范本。", "sig_en": "The boycott catapulted King to national prominence and proved the power of nonviolent mass protest, inspiring the broader protest movement of the late 1950s and 1960s.", "sig_zh": "抵制运动使金一举成名，并证明了非暴力群众抗议的力量，鼓舞了50年代末和60年代更广泛的抗议运动。", "exp_en": "Parks's 1955 arrest sparked a 381-day bus boycott led by Martin Luther King Jr., ending in a Supreme Court ruling against bus segregation. It made King a national leader and proved the power of nonviolent mass protest.", "exp_zh": "1955年帕克斯被捕引发381天的公交抵制运动，由金领导，最终以最高法院判决公交隔离违宪告终。它使金成为全国领袖，证明了非暴力群众抗议的力量。", "page": 881, "img": {"file": "img:f2_1520", "credit": "图源：Henretta《America's History》第8版 p.881"}}, {"id": "p8-027", "period": 8, "topic_en": "Southern Christian Leadership Conference (SCLC)", "topic_zh": "南方基督教领袖会议", "year": 1957, "year_text": "1957", "who": ["Martin Luther King Jr.", "Ralph Abernathy"], "who_zh": ["小马丁·路德·金", "拉尔夫·阿伯纳西"], "what_en": "In 1957, Martin Luther King Jr., the Reverend Ralph Abernathy, and dozens of black ministers from across the South founded the Atlanta-based Southern Christian Leadership Conference, through which the black church lent its moral and organizational strength to the civil rights movement.", "what_zh": "1957年，小马丁·路德·金、拉尔夫·阿伯纳西牧师和来自南方各地的数十名黑人牧师在亚特兰大创立南方基督教领袖会议，黑人教会由此将其道德与组织力量投入民权运动。", "cause_en": "The Montgomery Bus Boycott's success showed that southern black ministers and churches could coordinate an effective movement, and the SCLC was created to carry that model beyond Montgomery.", "cause_zh": "蒙哥马利抵制的成功表明南方黑人牧师和教会能够协调有效的运动，SCLC正是为把这一模式推广到蒙哥马利之外而创立。", "sig_en": "The SCLC quickly joined the NAACP at the leading edge of the movement for racial justice, and it would later lead the Birmingham campaign (1963) and the Selma march (1965).", "sig_zh": "SCLC迅速与NAACP并肩站上争取种族正义运动的前沿，后来领导了伯明翰运动（1963）和塞尔玛游行（1965）。", "exp_en": "Founded in 1957 by King and southern black ministers, the SCLC mobilized the black church's moral and organizational strength, joining the NAACP at the leading edge of the movement.", "exp_zh": "1957年由金与南方黑人牧师创立，南方基督教领袖会议动员黑人教会的道德与组织力量，与NAACP并肩站上运动前沿。", "page": 882, "img": {"file": "img:f2_1522", "credit": "图源：Henretta《America's History》第8版 p.882"}}, {"id": "p8-028", "period": 8, "topic_en": "Little Rock", "topic_zh": "小石城事件", "year": 1957, "year_text": "September 1957", "who": ["Orval Faubus", "Dwight D. Eisenhower"], "who_zh": ["奥瓦尔·福伯斯", "德怀特·艾森豪威尔"], "what_en": "In September 1957, when nine black students tried to enroll at all-white Central High School in Little Rock, Arkansas, Governor Orval Faubus called out the National Guard to bar them; President Eisenhower then sent 1,000 federal troops and nationalized the Arkansas National Guard to protect the students.", "what_zh": "1957年9月，9名黑人学生试图进入阿肯色州小石城全白人中央高中就读，州长奥瓦尔·福伯斯调动国民警卫队加以阻拦；艾森豪威尔总统随即派出1000名联邦军并接管阿肯色州国民警卫队，保护学生入学。", "cause_en": "Southern officials refused to enforce the Brown decision — Virginia's Harry F. Byrd called for massive resistance — and Eisenhower, though no champion of civil rights, was finally forced to act by open defiance of the law.", "cause_zh": "南方官员拒绝执行布朗案判决——弗吉尼亚的哈里·伯德呼吁大规模抵抗；虽非民权支持者，艾森豪威尔最终被公然蔑视法律的行为迫使出手。", "sig_en": "Eisenhower became the first president since Reconstruction to use federal troops to enforce the rights of African Americans, and the scenes of taunting mobs broadcast on television night after night exposed the violence of white supremacy to the nation.", "sig_zh": "艾森豪威尔成为重建以来首位动用联邦军队维护黑人权利的总统；电视上夜复一夜播放的辱骂暴徒画面，把白人至上主义的暴力暴露在全国面前。", "exp_en": "When Governor Faubus used the National Guard to block nine black students in 1957, Eisenhower sent 1,000 federal troops to Little Rock — the first such use since Reconstruction — exposing on television the violence of white resistance to Brown.", "exp_zh": "1957年福伯斯州长动用国民警卫队阻止9名黑人学生入学，艾森豪威尔派出1000名联邦军进驻小石城——重建以来联邦军队首次用于维护黑人权利，电视画面向全国暴露了白人抵抗布朗案的暴力。", "page": 879, "img": {"file": "img:f2_1512", "credit": "图源：Henretta《America's History》第8版 p.879"}}, {"id": "p8-029", "period": 8, "topic_en": "Greensboro Sit-Ins and SNCC", "topic_zh": "格林斯伯勒静坐与学生非暴力协调委员会", "year": 1960, "year_text": "February 1960", "who": ["Ella Baker", "Student Nonviolent Coordinating Committee (SNCC)"], "who_zh": ["埃拉·贝克", "学生非暴力协调委员会"], "what_en": "On February 1, 1960, four black college students sat at the whites-only Woolworth's lunch counter in Greensboro, North Carolina, and stayed until served; the tactic spread across the South, and inspired by the sit-ins, Ella Baker helped organize the Student Nonviolent Coordinating Committee (SNCC) in 1960.", "what_zh": "1960年2月1日，四名黑人大学生坐在北卡罗来纳州格林斯伯勒只接待白人的伍尔沃斯午餐柜台前静坐直到被服务；这一战术迅速扩散到整个南方，埃拉·贝克受此启发于1960年协助组织了学生非暴力协调委员会。", "cause_en": "The sit-ins were entirely the brainchild of the four students, who planned the action in their dorm rooms, and Baker's faith in grassroots, participatory democracy drew her to nurture the student activists.", "cause_zh": "静坐完全是四名学生在宿舍策划的自发行动；贝克对草根参与式民主的信念促使她去培育这些学生运动者。", "sig_en": "The Woolworth's counter was desegregated, sit-ins spread to other southern cities, and by year's end students had launched sit-ins in 126 cities with more than 50,000 participants and 3,600 jailed — drawing black college students into the movement in significant numbers for the first time, with SNCC emerging as its most important student protest organization.", "sig_zh": "伍尔沃斯柜台实现去隔离化，静坐扩散到其他南方城市；到年底，学生在126个城市发起静坐，5万多人参加、3600人被捕——非裔大学生首次大规模加入运动，SNCC成为运动中最重要的学生抗议组织。", "src": {"text": "Let's go down to Woolworth's tomorrow and ask for service, and the tactic is going to be simply this: we'll just stay there.", "attr": "Franklin McCain, one of the four Greensboro students, interviewed in My Soul Is Rested by Howell Raines (1977)"}, "exp_en": "The 1960 Greensboro sit-ins spread student nonviolent protest across the South and produced SNCC, the movement's most important student organization, bringing black college students into the struggle in large numbers for the first time.", "exp_zh": "1960年格林斯伯勒静坐把学生非暴力抗议扩散到整个南方，并催生了学生非暴力协调委员会——运动中最重要的学生组织，使非裔大学生首次大规模加入斗争。", "page": 882, "img": {"file": "img:f2_1522", "credit": "图源：Henretta《America's History》第8版 p.882"}}, {"id": "p8-030", "period": 8, "topic_en": "Freedom Rides", "topic_zh": "自由乘车运动", "year": 1961, "year_text": "1961", "who": ["Congress of Racial Equality (CORE)", "Robert Kennedy"], "who_zh": ["种族平等大会", "罗伯特·肯尼迪"], "what_en": "In 1961 the Congress of Racial Equality (CORE) organized Freedom Rides on interstate bus lines through the South to expose violations of Supreme Court rulings against segregation in interstate commerce; outside Anniston, Alabama, a bus was firebombed, and riders and reporters were brutally beaten in Birmingham and Montgomery while Governor John Patterson refused protection.", "what_zh": "1961年种族平等大会组织自由乘车队，乘坐州际巴士穿越南方，揭露南方无视最高法院关于州际交通去隔离化判决的行为；在阿拉巴马州安尼斯顿郊外，一辆巴士被燃烧弹炸毁，乘车者和记者在伯明翰和蒙哥马利遭残酷殴打，而州长约翰·帕特森拒绝提供保护。", "cause_en": "Recent Supreme Court rulings against segregation in interstate commerce were being blatantly violated in the South, and SNCC's sit-in tactics emboldened CORE to act.", "cause_zh": "最高法院关于州际交通去隔离化的判决在南方被公然违反；SNCC的静坐战术鼓舞了CORE采取行动。", "sig_en": "The beatings shown on the nightly news forced Attorney General Robert Kennedy to dispatch federal marshals, teaching activists the value of nonviolent protest that provoked violent white resistance.", "sig_zh": "晚间新闻播放的殴打画面迫使司法部长罗伯特·肯尼迪派出联邦法警；运动者从中学到：非暴力抗议若引发白人暴力抵抗，能迫使联邦介入。", "exp_en": "CORE's 1961 Freedom Rides exposed the South's defiance of rulings against segregated interstate travel; firebombings and beatings on the nightly news forced Attorney General Robert Kennedy to send federal marshals, teaching activists the power of nonviolent protest provoking violent white resistance.", "exp_zh": "1961年CORE的自由乘车揭露南方无视最高法院关于州际交通去隔离化的判决；燃烧弹与殴打画面登上晚间新闻，迫使司法部长罗伯特·肯尼迪派出联邦法警。运动者从中学到：非暴力抗议引发白人暴力抵抗，能迫使联邦介入。", "page": 882, "img": {"file": "img:f2_1522", "credit": "图源：Henretta《America's History》第8版 p.882"}}, {"id": "p8-031", "period": 8, "topic_en": "March on Washington for Jobs and Freedom", "topic_zh": "为工作与自由向华盛顿进军", "year": 1963, "year_text": "August 28, 1963", "who": ["A. Philip Randolph", "Bayard Rustin", "Martin Luther King Jr."], "who_zh": ["菲利普·伦道夫", "贝亚德·拉斯廷", "小马丁·路德·金"], "what_en": "On August 28, 1963, a quarter of a million people gathered at the Lincoln Memorial for the March on Washington for Jobs and Freedom, organized under the leadership of A. Philip Randolph and Bayard Rustin; Martin Luther King Jr.'s I Have a Dream speech marked the high point of the civil rights movement.", "what_zh": "1963年8月28日，25万人在林肯纪念堂参加为工作与自由向华盛顿进军，活动由菲利普·伦道夫和贝亚德·拉斯廷领导组织；小马丁·路德·金发表《我有一个梦想》演讲，标志着民权运动的最高潮。", "cause_en": "Civil rights leaders used the march tactic Randolph had first advanced in 1941 to marshal support for President Kennedy's civil rights bill, promised in June 1963 after the Birmingham crisis.", "cause_zh": "民权领袖沿用伦道夫1941年首倡的游行战术，为肯尼迪总统在伯明翰危机后于1963年6月承诺的民权法案争取支持。", "sig_en": "The sight of 250,000 blacks and whites marching together confirmed King as the leading spokesperson for the cause, though the march changed few congressional votes and a rift with militant young activists — SNCC's John Lewis was forced to tone down his speech — was already emerging.", "sig_zh": "25万黑白民众共同游行的场面确立了金作为运动首席代言人的地位；但游行本身改变的国会选票不多，且与激进青年运动者的裂痕已经显现——SNCC的约翰·刘易斯被迫软化了演讲措辞。", "exp_en": "The August 1963 March on Washington for Jobs and Freedom drew 250,000 people and King's I Have a Dream speech — the high point of the movement — though it changed few congressional votes by itself.", "exp_zh": "1963年8月为工作与自由向华盛顿进军，25万人齐聚林肯纪念堂，金发表《我有一个梦想》演讲——运动的最高潮，但本身并未改变多少国会选票。", "page": 886, "img": {"file": "img:f2_1535", "credit": "图源：Henretta《America's History》第8版 p.886"}}, {"id": "p8-032", "period": 8, "topic_en": "Civil Rights Act of 1964", "topic_zh": "1964年民权法案", "year": 1964, "year_text": "June 1964", "who": ["Lyndon B. Johnson"], "who_zh": ["林登·约翰逊"], "what_en": "In June 1964 Congress passed the most far-reaching civil rights law since Reconstruction: Title VII outlawed discrimination in employment on the basis of race, religion, national origin, and sex, another section guaranteed equal access to public accommodations and schools, and the law created the Equal Employment Opportunity Commission.", "what_zh": "1964年6月国会通过重建以来最深远的民权法：第七章禁止基于种族、宗教、国籍和性别的就业歧视，另一部分保障公共场所与学校平等准入，并设立平等就业机会委员会。", "cause_en": "The Birmingham campaign — Bull Connor's dogs, fire hoses, and cattle prods, King's Letter from Birmingham Jail, and the murder of Medgar Evers — plus the March on Washington pushed Kennedy to promise a bill in June 1963; after Kennedy's assassination, Johnson made passing it a priority and overcame the southern filibuster.", "cause_zh": "伯明翰运动——布尔·康纳的警犬、高压水枪和电牛棒，金的《伯明翰监狱来信》，梅德加·埃弗斯被暗杀——加上华盛顿大游行，促使肯尼迪1963年6月承诺立法；肯尼迪遇刺后，约翰逊把通过法案作为优先事项，挫败了南方参议员的阻挠议事。", "sig_en": "The act dismantled Jim Crow in public accommodations and employment and granted new enforcement powers to the attorney general, but it left obstacles to black voting rights untouched, so protesters went back into the streets.", "sig_zh": "法案瓦解了公共场所和就业领域的吉姆·克劳制，赋予司法部长新的执法权，但未触及黑人投票权的障碍，于是抗议者重返街头。", "exp_en": "The June 1964 Civil Rights Act — the most far-reaching since Reconstruction — outlawed discrimination in employment (Title VII) and public accommodations, created the EEOC, and gave the attorney general new enforcement powers.", "exp_zh": "1964年6月通过的《民权法案》是重建以来最深远的民权立法：第七章禁止就业歧视，保障公共场所平等准入，设立平等就业机会委员会，并赋予司法部长新的执法权。", "page": 890, "img": {"file": "img:f2_1547", "credit": "图源：Henretta《America's History》第8版 p.890"}}, {"id": "p8-033", "period": 8, "topic_en": "Voting Rights Act of 1965", "topic_zh": "1965年投票权法案", "year": 1965, "year_text": "August 6, 1965", "who": ["Martin Luther King Jr.", "Lyndon B. Johnson"], "who_zh": ["小马丁·路德·金", "林登·约翰逊"], "what_en": "Signed by President Johnson on August 6, 1965, the Voting Rights Act outlawed literacy tests and other devices that prevented African Americans from registering to vote and authorized the attorney general to send federal examiners to register voters in counties where registration was below 50 percent.", "what_zh": "1965年8月6日约翰逊总统签署的《投票权法案》，取缔文化测验等阻碍黑人登记投票的手段，并授权司法部长向登记率不足50%的县派遣联邦选举登记员。", "cause_en": "The Civil Rights Act had left voting barriers untouched; in March 1965 the SCLC's James Bevel called for a march from Selma to Montgomery, and the nationally televised police attack on marchers at the Edmund Pettus Bridge — Bloody Sunday — forced Johnson back to Congress.", "cause_zh": "《民权法案》未触及投票障碍；1965年3月SCLC的詹姆斯·贝维尔发起塞尔玛至蒙哥马利游行，州警在埃德蒙·佩特斯桥上对游行者的攻击（血腥星期日）经全国电视转播后，迫使约翰逊重返国会。", "sig_en": "Southern black registration rose from 20 percent in 1960 to 62 percent in 1971, the number of black elected officials quadrupled between 1970 and 1980, and the white monopoly on southern political power was broken — while the liberal New Deal coalition began to crumble as southern whites moved toward the Republican Party.", "sig_zh": "南方黑人登记率从1960年的20%升至1971年的62%，黑人当选官员数量在1970至1980年间翻了两番，白人对南方政治权力的垄断被打破——同时自由派新政联盟开始瓦解，南方白人转向共和党。", "exp_en": "After Bloody Sunday at Selma, the August 1965 Voting Rights Act outlawed literacy tests and authorized federal voter registrars; with the Twenty-fourth Amendment ending poll taxes, southern black registration rose from 20 percent in 1960 to 62 percent in 1971.", "exp_zh": "塞尔玛血腥星期日之后，1965年8月《投票权法案》取缔文化测验并授权联邦派选举登记员；加上第二十四修正案废除人头税，南方黑人登记率从1960年的20%升至1971年的62%。", "page": 891, "img": {"file": "img:f2_1549", "credit": "图源：Henretta《America's History》第8版 p.891"}}, {"id": "p8-034", "period": 8, "topic_en": "Malcolm X", "topic_zh": "马尔科姆·X", "year": 1965, "year_text": "February 21, 1965", "who": ["Malcolm X", "Elijah Muhammad"], "who_zh": ["马尔科姆·X", "以利亚·穆罕默德"], "what_en": "The most charismatic Black Muslim, Malcolm X preached a philosophy of militant separatism — advocating violence only for self-defense — and scorned the 1963 March on Washington as the Farce on Washington; after breaking with the Nation of Islam in 1964, he was assassinated on February 21, 1965, while delivering a speech in Harlem.", "what_zh": "最具魅力的黑人穆斯林领袖马尔科姆·X宣扬激进分离主义——仅支持为自卫而使用暴力，并讥讽1963年华盛顿大游行为'华盛顿闹剧'；1964年与伊斯兰民族组织决裂后，于1965年2月21日在哈莱姆演讲时遇刺。", "cause_en": "As the leading exponent of black nationalism, Malcolm X believed strengthening the black community was a surer path to freedom than changing the minds of hostile whites; a power struggle with founder Elijah Muhammad led him to leave the Nation in 1964.", "cause_zh": "作为黑人民族主义的首席代表，马尔科姆·X认为壮大黑人社区比改变敌视的白人观念更可靠；与创始人以利亚·穆罕默德的权力斗争使他于1964年脱离该组织。", "sig_en": "Three Black Muslims were convicted of his murder; his emphasis on black pride and self-help, and his unrelenting criticism of white supremacy, made him one of the freedom movement's most inspirational figures, in life and long after his death.", "sig_zh": "三名黑人穆斯林因谋杀他被定罪；他对黑人自豪和自助的强调、对白人至上主义毫不留情的批判，使他成为自由运动中最具感召力的人物，生前如此，身后亦然。", "exp_en": "The Nation of Islam's most charismatic minister, Malcolm X preached black pride, self-help, and militant separatism; after breaking with the Nation in 1964 he was assassinated in 1965, becoming a lasting inspiration for Black Power.", "exp_zh": "伊斯兰民族组织最具魅力的部长，马尔科姆·X倡导黑人自豪、自助与激进分离主义；1964年与该组织决裂后于1965年遇刺，成为黑人权力运动长久的精神象征。", "page": 892}, {"id": "p8-035", "period": 8, "topic_en": "Black Power and the Black Panther Party", "topic_zh": "黑人权力与黑豹党", "year": 1966, "year_text": "1966", "who": ["Stokely Carmichael", "Huey Newton", "Bobby Seale"], "who_zh": ["斯托克利·卡迈克尔", "休伊·牛顿", "鲍比·西尔"], "what_en": "In 1966, SNCC and CORE activists following Stokely Carmichael began calling for black self-reliance under the banner of Black Power, while in Oakland, California, college students Huey Newton and Bobby Seale founded the militant Black Panther Party to protect African Americans from police violence, issuing the Ten Point Program in their manifesto What We Want, What We Believe.", "what_zh": "1966年，追随斯托克利·卡迈克尔的SNCC和CORE活动家打出黑人权力旗号，呼吁黑人自立；同时，两名大学生休伊·牛顿和鲍比·西尔在加州奥克兰创立激进的黑豹党，保护黑人免受警察暴力，并在宣言《我们要什么，我们信什么》中提出十点纲领。", "cause_en": "Frustrated by the slow pace of reform and the limits of civil rights laws, Black Power advocates asked whether alliances with whites made African Americans dependent on white goodwill, and concluded that blacks should build economic and political power in their own communities.", "cause_zh": "对改革缓慢和民权法律局限的失望，使黑人权力倡导者质疑：与白人的联盟是否让黑人依赖白人的善意；他们得出结论：黑人应在自己的社区建立经济与政治力量。", "sig_en": "Black Power shifted the movement from legal equality toward racial pride, self-determination, and community control, inspiring the Chicano, American Indian, and other movements; the Panthers' free breakfast program and sickle-cell anemia testing won popular support, though armed self-defense brought violent clashes with police and FBI disruption under COINTELPRO.", "sig_zh": "黑人权力把运动重心从法律平等转向种族自豪、自决和社区自治，鼓舞了奇卡诺、印第安人等运动；黑豹党的免费早餐和镰状细胞贫血检测赢得民众支持，但武装自卫也带来与警察的暴力冲突和联邦调查局反情报计划的破坏。", "src": {"text": "The concept of Black Power rests on a fundamental premise: Before a group can enter the open society, it must first close ranks.", "attr": "Stokely Carmichael and Charles V. Hamilton, Black Power: The Politics of Liberation (1967)"}, "exp_en": "Black Power — proclaimed by Stokely Carmichael in 1966 — demanded black self-reliance and community control; the Black Panther Party (founded in Oakland by Huey Newton and Bobby Seale) combined armed self-defense against police violence with community programs like free breakfasts for children.", "exp_zh": "1966年卡迈克尔打出黑人权力旗号，主张黑人自立与社区自治；黑豹党（休伊·牛顿、鲍比·西尔在奥克兰创立）将反警察暴力的武装自卫与免费早餐等社区项目结合起来。", "page": 893, "img": {"file": "img:f2_1555", "credit": "图源：Henretta《America's History》第8版 p.893"}}, {"id": "p8-036", "period": 8, "topic_en": "The Economic Opportunity Act of 1964 and the War on Poverty", "topic_zh": "《经济机会法》(1964)与“向贫困宣战”", "year": 1964, "year_text": "1964", "who": ["Lyndon B. Johnson"], "who_zh": ["林登·约翰逊"], "what_en": "The Economic Opportunity Act of 1964 created a series of programs — including Head Start, the Job Corps, Upward Bound, and Volunteers in Service to America (VISTA) — to reach Americans living in poverty, launching President Johnson's War on Poverty.", "what_zh": "1964年《经济机会法》创建了一系列项目——包括学前教育计划（Head Start）、就业团（Job Corps）、向上跃升计划（Upward Bound）和美国志愿服务队（VISTA），覆盖生活在贫困中的美国人，打响了约翰逊总统的“向贫困宣战”。", "cause_en": "Johnson called it a national disgrace that one-fifth of Americans — hidden in Appalachia, urban ghettos, migrant labor camps, and Indian reservations — lived in poverty, yet declared that 'for the first time in our history, it is possible to conquer poverty.'", "cause_zh": "约翰逊称全国五分之一人口（隐匿于阿巴拉契亚、城市贫民区、流动劳工营和印第安保留地）生活贫困是国家的耻辱，却又宣称“我国历史上第一次有可能征服贫困”。", "sig_en": "The poverty rate fell from 20 percent to 13 percent between 1963 and 1968, but conservative critics accused liberals of believing every social problem could be solved with a government program, while entrenched poverty and urban racial segregation persisted.", "sig_zh": "贫困率从1963年的20%降至1968年的13%，但保守派批评自由派认为任何社会问题都能靠政府项目解决，而顽固的贫困和城市种族隔离依然存在。", "exp_en": "The War on Poverty embodied Great Society liberalism's faith in federal action against poverty, producing Head Start and VISTA; its mixed results fed the conservative critique of big government.", "exp_zh": "“向贫困宣战”体现了“伟大社会”自由主义对联邦政府消除贫困的信心，催生了学前教育计划和志愿服务队；其褒贬不一的结果助长了保守派对大政府的批判。", "page": 905, "img": {"file": "img:f2_1584", "credit": "图源：Henretta《America's History》第8版 p.905"}}, {"id": "p8-037", "period": 8, "topic_en": "Medicare and Medicaid", "topic_zh": "联邦医疗保险（Medicare）与医疗补助（Medicaid）", "year": 1965, "year_text": "1965", "who": ["Lyndon B. Johnson"], "who_zh": ["林登·约翰逊"], "what_en": "Johnson won passage of two new programs: Medicare, a health plan for the elderly funded by a surcharge on Social Security payroll taxes, and Medicaid, a health plan for the poor paid for by general tax revenues and administered by the states.", "what_zh": "约翰逊推动通过了两个新项目：Medicare（老年人医保，资金来自社会保障工资税附加费）和Medicaid（穷人医保，资金来自一般税收、由各州管理）。", "cause_en": "Johnson's 1964 landslide gave him congressional majorities rivaling FDR's in 1935 — just what he needed to push the Great Society forward, including national health insurance.", "cause_zh": "约翰逊1964年压倒性胜选带来了堪比1935年罗斯福时期的国会多数——这正是他推进“伟大社会”（包括国民健康保险）所需要的。", "sig_en": "The book calls Medicare and Medicaid 'the most enduring of the Great Society programs,' helping millions of elderly and poor citizens afford necessary health care and dramatically improving the financial situation of the elderly.", "sig_zh": "教材称Medicare和Medicaid是“伟大社会项目中最持久的”，帮助数百万老年人和穷人负担必要的医疗，大幅改善了老年人的经济状况。", "exp_en": "Medicare and Medicaid were the Great Society's signature social-welfare achievements, extending the New Deal state into health care for the elderly and the poor.", "exp_zh": "Medicare和Medicaid是“伟大社会”标志性的社会福利成就，把罗斯福新政国家扩展到了老年人和穷人的医疗领域。", "page": 906, "img": {"file": "img:f2_1586", "credit": "图源：Henretta《America's History》第8版 p.906"}}, {"id": "p8-038", "period": 8, "topic_en": "The Immigration Act of 1965", "topic_zh": "1965年《移民法》", "year": 1965, "year_text": "1965", "who": ["Lyndon B. Johnson"], "who_zh": ["林登·约翰逊"], "what_en": "The Immigration Act of 1965 abandoned the quota system that favored northern Europeans, replacing it with numerical limits that did not discriminate among nations; close relatives of legal residents could be admitted outside the numerical limits to promote family reunification.", "what_zh": "1965年《移民法》废除了偏袒北欧人的配额制度，改为不按国别歧视的数额限制；合法居民的近亲属可不受名额限制入境，以促进家庭团聚。", "cause_en": "At this moment of reform zeal under the Great Society, it became possible to tackle the nation's discriminatory immigration policy.", "cause_zh": "在“伟大社会”改革热潮中，终于有可能解决美国歧视性的移民政策。", "sig_en": "Since 1965, immigrants from Asia and Latin America — who especially benefited from the family-reunification exception — have become increasingly visible in American society, transforming the nation's racial and ethnic composition.", "sig_zh": "1965年之后，来自亚洲和拉丁美洲的移民（尤其受益于家庭团聚例外）在美国社会中日益显著，改变了美国的种族与族裔构成。", "exp_en": "The 1965 act ended the national-origins quota era of 1924 and opened a new chapter of non-European immigration to the United States.", "exp_zh": "1965年法案终结了1924年以来按国别配额的时代，开启了美国非欧洲移民的新篇章。", "page": 906, "img": {"file": "img:f2_1586", "credit": "图源：Henretta《America's History》第8版 p.906"}}, {"id": "p8-039", "period": 8, "topic_en": "The Gulf of Tonkin Resolution", "topic_zh": "北部湾决议案", "year": 1964, "year_text": "August 1964", "who": ["Lyndon B. Johnson"], "who_zh": ["林登·约翰逊"], "what_en": "After reports that North Vietnamese torpedo boats fired on the U.S. destroyer Maddox in the Gulf of Tonkin — the August 4 attack later proved to be only misread radar sightings — Congress, with only two senators voting no, authorized Johnson to 'take all necessary measures' to repel attacks and prevent further aggression.", "what_zh": "在据报北越鱼雷艇在北部湾袭击美军驱逐舰“马多克斯”号之后（8月4日的第二次袭击后来证明只是误读的雷达信号），国会以仅两名参议员反对的结果，授权约翰逊“采取一切必要措施”击退攻击、防止进一步侵略。", "cause_en": "Johnson vowed 'I am not going to lose Vietnam,' believing withdrawal would weaken America's credibility; convinced a wider war was inevitable, he issued a call to arms whether the attack was real or imagined.", "cause_zh": "约翰逊发誓“我不会失去越南”，认为撤退会损害美国的信誉；他认定更大规模的战争不可避免，无论袭击真假都发出了战争动员。", "sig_en": "The resolution gave Johnson the freedom to conduct operations in Vietnam as he saw fit, becoming the legal foundation for the full Americanization of the war beginning in 1965.", "sig_zh": "该决议赋予约翰逊在越南按自己意愿行动的自由，成为1965年起美国全面接管越战的法律基础。", "exp_en": "The Gulf of Tonkin Resolution showed how a questionable incident could produce a near-unanimous blank check for war, a precedent later cited against unchecked presidential war powers.", "exp_zh": "北部湾决议案表明，一起可疑事件如何换来近乎全票的战争空白支票，这一先例后来成为批评总统战争权力不受制约的依据。", "page": 911, "img": {"file": "img:f2_1605", "credit": "图源：Henretta《America's History》第8版 p.911"}}, {"id": "p8-040", "period": 8, "topic_en": "The Tet Offensive", "topic_zh": "春节攻势", "year": 1968, "year_text": "January 30, 1968", "who": ["Vietcong", "North Vietnamese forces"], "who_zh": ["越共", "北越军队"], "what_en": "On January 30, 1968, the Vietcong unleashed a massive, well-coordinated assault timed to the Tet new year, striking 36 provincial capitals and five of six major cities and nearly overrunning the U.S. embassy in Saigon; in strictly military terms it failed, with very heavy Vietcong losses.", "what_zh": "1968年1月30日，越共趁春节（Tet）发动大规模协同突袭，攻击36个省会和六大城市中的五个，几乎攻入美国驻西贡大使馆；纯军事上它以越共惨重损失告终。", "cause_en": "Johnson and his generals kept insisting there was 'light at the end of the tunnel,' but North Vietnamese and Vietcong forces fought on and American casualties had mounted to several hundred a week.", "cause_zh": "约翰逊及其将领们一直宣称“隧道尽头有光”，但北越和越共持续作战，美军每周伤亡已达数百人。", "sig_en": "Tet made a mockery of claims the U.S. was winning; three months later doves outnumbered hawks 42 to 41 percent, the offensive undermined Johnson and discredited his war policies, and on March 31 he stunned the nation by announcing he would not seek reelection.", "sig_zh": "春节攻势让美国“即将胜利”的宣称成为笑柄；三个月后反战派在民调中以42%对41%超过主战派，约翰逊的战争政策信誉扫地，他于3月31日震惊全国地宣布不再竞选连任。", "exp_en": "Tet was the psychological turning point of the Vietnam War: a military defeat for the Vietcong that destroyed American confidence that the war was winnable.", "exp_zh": "春节攻势是越战的心理转折点：越共的军事失败反而摧毁了美国人对战争可以取胜的信心。", "page": 919}, {"id": "p8-041", "period": 8, "topic_en": "The Free Speech Movement and the Counterculture", "topic_zh": "言论自由运动与反主流文化", "year": 1964, "year_text": "fall 1964", "who": ["Mario Savio"], "who_zh": ["马里奥·萨维奥"], "what_en": "In fall 1964, after UC Berkeley administrators banned student political activity on campus, student organizations formed the Free Speech Movement and staged a sit-in at the administration building; meanwhile the hippie counterculture — the 1967 Summer of Love, the 1969 Woodstock concert of 400,000 youths — mounted a general revolt against authority and middle-class respectability.", "what_zh": "1964年秋，加州大学伯克利分校校方禁止学生在校内从事政治活动，学生组织组成“言论自由运动”并在行政楼静坐抗议；与此同时，嬉皮士反主流文化——1967年“爱之夏”、1969年40万人参加的伍德斯托克音乐节——掀起了对权威和中产阶级体面价值观的全面反叛。", "cause_en": "College students inspired by the civil rights movement began agitating for change; Mario Savio compared Berkeley's struggle to the Southern civil rights struggle, and some students had just returned radicalized from Freedom Summer in Mississippi.", "cause_zh": "受民权运动鼓舞的大学生开始为变革奔走；萨维奥把伯克利的斗争比作南方的民权斗争，一些学生刚从密西西比“自由之夏”归来、思想激进化。", "sig_en": "Emboldened by Berkeley, students nationwide protested university policies and the Vietnam War, fueling the New Left and the broader youth rebellion that tore at the Democratic coalition and provoked a conservative backlash.", "sig_zh": "伯克利的榜样鼓舞了全国大学生抗议校方政策和越战，推动了新左派和更广泛的青年反叛，加剧了民主党联盟的分裂并引发保守派反弹。", "exp_en": "The Free Speech Movement launched campus-based New Left politics, while the counterculture's apolitical 'peace and love' rebellion deepened the generational divide.", "exp_zh": "言论自由运动开启了校园新左派政治，而反主流文化非政治化的“和平与爱”反叛加深了代际鸿沟。", "page": 914}, {"id": "p8-042", "period": 8, "topic_en": "Women's Liberation", "topic_zh": "妇女解放运动", "year": 1968, "year_text": "1968", "who": ["Betty Friedan", "Gloria Steinem"], "who_zh": ["贝蒂·弗里丹", "格洛丽亚·斯泰纳姆"], "what_en": "In 1968 a new brand of feminism emerged: women's liberation — younger, college-educated women, many fresh from the New Left and antiwar movements, who broke away and organized in loose collectives; it went public at the 1968 Miss America pageant protest, introduced terms like 'sexism,' and peaked with the August 1970 Women's Strike for Equality.", "what_zh": "1968年出现了新形态的女性主义：妇女解放运动——主要是受过大学教育的年轻女性，多来自新左派和反战运动，她们脱离原有运动、自行组成松散集体；1968年“美国小姐”选美抗议让运动公开亮相，“性别歧视”等新词进入国民词汇，1970年8月“妇女争取平等大罢工”达到高潮。", "cause_en": "These feminists were inspired by the civil rights movement but frustrated that it ignored women, and they discovered that male leaders of the New Left and antiwar movements treated women as little more than helpers who typed memos and fetched coffee.", "cause_zh": "她们受民权运动鼓舞，却因运动忽视女性而失望，还发现新左派和反战运动的男性领袖把女性当成打字倒咖啡的帮手。", "sig_en": "Women's liberation campaigned for reproductive rights and an end to women's denigration, helped win Title IX (1972) banning sex discrimination in federally funded education, and challenged Cold War liberalism — fracturing the old Democratic coalition.", "sig_zh": "妇女解放运动为生育权和终结对女性的贬低而斗争，推动了1972年《教育法第九条》（禁止接受联邦资金的教育机构性别歧视），挑战了冷战自由主义——使旧民主党联盟出现裂痕。", "exp_en": "Women's liberation marked feminism's radical turn after NOW's legal-equality strategy, shifting the movement from equal opportunity to transforming a culture that treated women as sexual objects.", "exp_zh": "妇女解放运动标志着女性主义在全国妇女组织法律平等策略之后的激进转向，从争取机会平等转向改造把女性物化的文化。", "page": 924, "img": {"file": "img:f2_1641", "credit": "图源：Henretta《America's History》第8版 p.924"}}, {"id": "p8-043", "period": 8, "topic_en": "The Stonewall Riots", "topic_zh": "石墙骚乱", "year": 1969, "year_text": "June 1969", "who": ["gay liberation activists"], "who_zh": ["同性恋解放活动家"], "what_en": "In June 1969, when police raided the Stonewall Inn, a gay bar in New York's Greenwich Village, its patrons rioted for two days, burning the bar and battling police in the streets; inspired by Black Power and the women's movement, activists celebrated the riots as a symbolic demand for full citizenship.", "what_zh": "1969年6月，警方突袭纽约格林威治村的同性恋酒吧石墙酒吧后，顾客们连续两天暴动，烧毁酒吧、与警察在街头对峙；受黑人力量和妇女运动鼓舞，活动家把骚乱视为要求完全公民权的象征性诉求。", "cause_en": "Police had raided gay bars for decades, arresting patrons and publicizing their names; homosexuality was considered immoral and was illegal in most states, and decades of police repression had taken their toll.", "cause_zh": "几十年来警方一直在突袭同性恋酒吧、逮捕顾客并公布姓名；同性恋被视为不道德、在大多数州属非法，数十年的压制终于引发爆发。", "sig_en": "The gay liberation movement grew quickly after Stonewall: local organizations proliferated, activists pushed for nondiscrimination ordinances, and by 1975 the National Gay Task Force was lobbying Congress.", "sig_zh": "石墙之后同性恋解放运动迅速壮大：地方组织激增，活动家推动反歧视条例，到1975年全国同性恋特别工作组已在国会游说。", "exp_en": "Stonewall transformed gay rights from the respectable, quiet homophile activism of the 1950s–60s into a militant liberation movement under the banner of 'coming out.'", "exp_zh": "石墙把同性恋权利运动从1950–60年代体面低调的“亲同”活动，变成了打着“出柜”旗号的激进解放运动。", "page": 926, "img": {"file": "img:f2_1647", "credit": "图源：Henretta《America's History》第8版 p.926"}}, {"id": "p8-044", "period": 8, "topic_en": "The Riot at the 1968 Democratic National Convention", "topic_zh": "1968年民主党全国代表大会骚乱", "year": 1968, "year_text": "August 1968", "who": ["Richard J. Daley", "Abbie Hoffman", "Jerry Rubin"], "who_zh": ["理查德·戴利", "艾比·霍夫曼", "杰里·鲁宾"], "what_en": "At the August 1968 Democratic National Convention in Chicago, thousands of antiwar protesters descended on the city; Mayor Richard J. Daley ordered police to break up the demonstrations, and officers attacked protesters with tear gas and clubs in what an official report later called a 'police riot,' all broadcast on television during the nominating speeches.", "what_zh": "1968年8月芝加哥民主党全国代表大会期间，数千名反战示威者涌入该市；戴利市长下令警察驱散示威，警察用催泪瓦斯和警棍攻击抗议者，官方报告后来称之为“警察暴乱”，而电视在提名演讲期间全程直播了暴力场面。", "cause_en": "Anger at Johnson and the Democratic Party — fueled by the Tet offensive, the assassinations of Martin Luther King Jr. and Robert Kennedy, and the youth rebellion — had radicalized the antiwar movement, whose activists came to Chicago determined to stop the war.", "cause_zh": "对约翰逊和民主党的愤怒——在春节攻势、马丁·路德·金和罗伯特·肯尼迪遇刺及青年反叛的激化下——使反战运动激进化，活动家们决心到芝加哥阻止战争。", "sig_en": "The televised violence cemented the image of Democrats as the party of disorder; the dispirited convention nominated Hubert H. Humphrey on a middle-of-the-road platform, and the crisis of liberalism became unmanageable.", "sig_zh": "电视直播的暴力坐实了民主党“混乱之党”的形象；士气低落的大会提名汉弗莱、党纲走中间路线，自由主义的危机变得不可收拾。", "exp_en": "The Siege of Chicago displayed the collapse of the New Deal coalition's unity over Vietnam and handed Nixon's 'law and order' appeal its most vivid exhibit.", "exp_zh": "“芝加哥之围”展现了新政联盟在越战问题上的团结崩溃，也为尼克松“法律与秩序”的诉求提供了最生动的例证。", "page": 921, "img": {"file": "img:f2_1630", "credit": "图源：Henretta《America's History》第8版 p.921"}}, {"id": "p8-045", "period": 8, "topic_en": "Nixon's Visit to China and Détente", "topic_zh": "尼克松访华与缓和政策", "year": 1972, "year_text": "February 1972", "who": ["Richard M. Nixon", "Henry Kissinger"], "who_zh": ["理查德·尼克松", "亨利·基辛格"], "what_en": "In 1972 Nixon became the first sitting U.S. president to visit China, pledging better relations on a televised week-long trip and declaring the two nations could peacefully coexist; with the SALT I treaty signed with Soviet premier Leonid Brezhnev, this was the centerpiece of his détente — a lessening of Cold War tensions — guided by national security advisor Henry Kissinger.", "what_zh": "1972年尼克松成为首位访问中国的在任美国总统，在电视直播的一周行程中承诺改善两国关系、宣称两国可以和平共处；这与同苏联领导人勃列日涅夫签订的第一阶段限制战略武器条约（SALT I）一起，构成其缓和政策（缓解冷战紧张）的核心，由国家安全顾问基辛格主导。", "cause_en": "Nixon's impeccable anticommunist credentials — he had risen in the 1950s railing against Democrats for 'losing' China — gave him political cover to go to Beijing; he also hoped to play the Soviets and Chinese against each other for a better deal on Vietnam at the Paris peace talks.", "cause_zh": "尼克松无可挑剔的反共资历——他1950年代正是靠指责民主党“丢失中国”起家——给了他访华的政治掩护；他也希望打“苏联牌”对“中国牌”，在巴黎和谈中为越南问题换取更好的交易。", "sig_en": "Praised for lessening Cold War tensions, the visit was détente's tactical high point, though the hoped-for Vietnam bargain never materialized and the strategy cost more lives through continued bombing.", "sig_zh": "此次访问因缓解冷战紧张而受到赞誉，成为缓和政策的战术高点，尽管期望中的越南交易并未实现，持续的轰炸反而造成更多生命损失。", "exp_en": "Nixon's opening to China showed how an ardent anticommunist could do what liberals only talked about, reshaping Cold War diplomacy into triangular U.S.-Soviet-Chinese relations.", "exp_zh": "尼克松打开中国大门表明，一位坚定的反共者能做到自由派只敢空谈的事，把冷战外交重塑为美苏中三角关系。", "page": 929}, {"id": "p8-046", "period": 8, "topic_en": "The OPEC Oil Embargo", "topic_zh": "欧佩克石油禁运", "year": 1973, "year_text": "October 1973", "who": ["Organization of Petroleum Exporting Countries (OPEC)"], "who_zh": ["石油输出国组织（欧佩克）"], "what_en": "In response to U.S. support for Israel in the 1973 Yom Kippur War, the Arab states in OPEC declared an oil embargo in October 1973; U.S. gas prices jumped 40 percent and heating oil 30 percent, and Americans waited in mile-long lines at gas stations through the winter of 1973–1974.", "what_zh": "为回应美国在1973年赎罪日战争中支持以色列，欧佩克阿拉伯成员国于1973年10月宣布石油禁运；美国汽油价格飙升40%、取暖油上涨30%，整个1973–74年冬季美国人排起数英里长的加油长队。", "cause_en": "In the 1973 Yom Kippur War, Egypt and Syria invaded Israel to regain territory lost in 1967; Israel prevailed only after an emergency American airlift, prompting the Arab oil states to retaliate against U.S. support.", "cause_zh": "1973年赎罪日战争中，埃及和叙利亚进攻以色列以收复1967年失去的领土；以色列靠美国紧急空运才获胜，阿拉伯产油国遂对美国的支援进行报复。", "sig_en": "Oil became a political weapon and the West's vulnerability stood revealed; the embargo compounded raging inflation, Congress imposed a 55 mph national speed limit, and Americans shifted to fuel-efficient foreign cars — deepening the 'era of limits.'", "sig_zh": "石油成为政治武器，西方的脆弱暴露无遗；禁运加剧了恶性通胀，国会实施55英里全国限速，美国人转向省油的外国车——“有限时代”进一步加深。", "exp_en": "The embargo ended the postwar assumption of cheap, limitless energy and tied Middle East politics directly to the American household economy.", "exp_zh": "禁运终结了战后“廉价无限能源”的假设，把中东政治与美国家庭经济直接挂钩。", "page": 938}, {"id": "p8-047", "period": 8, "topic_en": "Environmentalism, Earth Day, and the EPA", "topic_zh": "环保运动、地球日与环保署", "year": 1970, "year_text": "1970", "who": ["Rachel Carson"], "who_zh": ["蕾切尔·卡森"], "what_en": "Environmentalism became a certifiable mass movement on the first Earth Day, April 22, 1970, when 20 million citizens rallied for a cleaner planet; earlier that year Congress passed the National Environmental Policy Act creating the Environmental Protection Agency (EPA), followed by the Clean Air Act, the Water Pollution Control Act, and the Endangered Species Act.", "what_zh": "1970年4月22日首个地球日，2000万美国人集会支持更清洁的地球，环保运动成为名副其实的群众运动；同年早些时候国会通过《国家环境政策法》成立环保署（EPA），随后又通过了《清洁空气法》《水污染控制法》和《濒危物种法》。", "cause_en": "Rachel Carson's Silent Spring (1962) exposed DDT's toxic impact; the 1969 Santa Barbara oil spill, the Cuyahoga River catching fire, and the energy crisis drove home that the earth's resources are not limitless.", "cause_zh": "卡森1962年《寂静的春天》揭露了DDT的毒害；1969年圣巴巴拉石油泄漏、凯霍加河起火，以及能源危机，共同让人意识到地球资源并非无限。", "sig_en": "A bipartisan coalition with President Nixon's support passed landmark environmental laws, though corporations and workers resisted regulation and by the 1980s environmentalism starkly divided Americans over growth versus limits.", "sig_zh": "在尼克松总统支持的两党联盟推动下，一系列里程碑式环保法律得以通过；但企业和工人抵制监管，到1980年代环保主义在增长与设限两派之间造成了尖锐分裂。", "exp_en": "Earth Day and the EPA marked environmentalism's arrival as a mainstream political force, extending 1960s activism from civil rights to the natural world.", "exp_zh": "地球日和环保署标志着环保主义成为主流政治力量，把1960年代的 activism 从民权扩展到了自然界。", "page": 939, "img": {"file": "img:f2_1682", "credit": "图源：Henretta《America's History》第8版 p.939"}}, {"id": "p8-048", "period": 8, "topic_en": "The Three Mile Island Accident", "topic_zh": "三哩岛核事故", "year": 1979, "year_text": "March 1979", "who": ["environmentalists"], "who_zh": ["环保人士"], "what_en": "In March 1979 the reactor core at the Three Mile Island nuclear plant near Harrisburg, Pennsylvania, came close to meltdown; more than 100,000 people fled their homes, and after the incident no new nuclear plants were authorized.", "what_zh": "1979年3月，宾夕法尼亚州哈里斯堡附近的三哩岛核电站堆芯接近熔毁，十多万人逃离家园；事故之后再也没有新的核电站获批。", "cause_en": "Environmentalists had publicized the dangers of nuclear power — a reactor meltdown would be catastrophic — even as the oil crisis made nuclear energy seem like a godsend, with 42 plants operating and 100 more planned by 1974.", "cause_zh": "环保人士一直在宣传核电的危险——堆芯熔毁将是灾难性的——而当时石油危机让核电看似天赐良机，到1974年已有42座核电站在运行、100座在规划。", "sig_en": "The near-catastrophe enabled environmentalists to win the battle over nuclear energy, capping the growth of a technology once greeted with enthusiasm and sharpening the 1980s divide between growth advocates and activists preaching limits.", "sig_zh": "这场几近灾难的事故让环保人士赢得了核电之争，遏制了一种曾被寄予厚望的技术的发展，并加剧了1980年代主张增长与主张设限两派的分裂。", "exp_en": "Three Mile Island showed how a single accident could halt an entire energy technology, making safety fears the decisive factor in U.S. nuclear policy.", "exp_zh": "三哩岛表明，一次事故就能叫停整项能源技术，安全恐惧成为美国核政策的决定性因素。", "page": 942}, {"id": "p8-049", "period": 8, "topic_en": "Stagflation", "topic_zh": "滞胀", "year": null, "year_text": "the 1970s", "who": ["Richard Nixon", "Gerald Ford", "Jimmy Carter"], "who_zh": ["理查德·尼克松", "杰拉尔德·福特", "吉米·卡特"], "what_en": "In the 1970s the U.S. economy was hit simultaneously by unemployment, stagnant consumer demand, and inflation — a combination called stagflation — contradicting the economists' principle that prices were not supposed to rise in a stagnant economy; discretionary income per worker dropped 18 percent between 1973 and 1982.", "what_zh": "1970年代美国经济同时遭受失业、消费需求停滞和通胀的打击——这种组合被称为滞胀，违背了经济学家“停滞经济中物价不应上涨”的原则；1973至1982年间工人可支配收入下降了18%。", "cause_en": "Vietnam War and Great Society spending produced a growing federal deficit and spiraling inflation, foreign competition intensified, and the 1973 oil embargo compounded the distress with raging inflation.", "cause_zh": "越战和“伟大社会”开支造成联邦赤字扩大、通胀螺旋上升，外国竞争加剧，1973年石油禁运又叠加了恶性通胀的困境。", "sig_en": "None of the decade's three presidents — Nixon, Ford, or Carter — had much luck tackling it; Nixon's 1971 wage-price controls and removal of the U.S. from the gold standard (ending Bretton Woods), Ford's WIN campaign, and Carter's policies all failed, discrediting the Keynesian consensus and opening the door to deregulation and tax cuts.", "sig_zh": "三位总统——尼克松、福特、卡特——都束手无策；尼克松1971年的工资物价管制和让美元脱离金本位（终结布雷顿森林体系）、福特的“立即抑制通胀”运动、卡特的政策全部失败，凯恩斯共识信誉扫地，为放松管制和减税打开了大门。", "exp_en": "Stagflation was the economic signature of the 1970s 'era of limits,' undermining postwar liberal economic management and fueling the conservative turn.", "exp_zh": "滞胀是1970年代“有限时代”的经济标志，它动摇了战后自由派的经济管理模式，推动了保守派转向。", "page": 942}, {"id": "p8-050", "period": 8, "topic_en": "Watergate and Nixon's Resignation", "topic_zh": "水门事件与尼克松辞职", "year": 1974, "year_text": "break-in June 1972; resignation August 9, 1974", "who": ["Richard M. Nixon", "G. Gordon Liddy", "E. Howard Hunt", "Carl Bernstein", "Bob Woodward"], "who_zh": ["理查德·尼克松", "G·戈登·利迪", "E·霍华德·亨特", "卡尔·伯恩斯坦", "鲍勃·伍德沃德"], "what_en": "On June 17, 1972, five men carrying wiretapping equipment were caught breaking into Democratic National Committee headquarters at the Watergate complex; the burglary was part of a White House campaign of 'dirty tricks,' and after Nixon obstructed the FBI investigation, the House Judiciary Committee began considering impeachment — on August 9, 1974, Nixon became the first U.S. president to resign.", "what_zh": "1972年6月17日，五名携带窃听设备的男子在水门大厦民主党全国委员会总部行窃被抓；这是白宫“肮脏伎俩”竞选的一部分，尼克松阻挠FBI调查后，众议院司法委员会启动弹劾程序——1974年8月9日，尼克松成为美国历史上首位辞职的总统。", "cause_en": "Obsessed with his enemies, Nixon arranged hush money for the burglars and instructed the CIA to stop the FBI investigation — obstruction of justice — instead of firing his guilty aides and letting justice take its course.", "cause_zh": "出于对政敌的执念，尼克松安排封口费并指示CIA阻止FBI调查——构成妨碍司法——而不是开除涉案助手、让司法走正常程序。", "sig_en": "Watergate produced post-scandal reforms (the War Powers Act, Freedom of Information Act amendments, the Ethics in Government Act), 75 new 'Watergate baby' Democrats in the 1974 midterms, deepened popular disdain for politicians, and shifted the Republican Party to the right.", "sig_zh": "水门事件催生了丑闻后改革（《战争权力法》、信息自由法修正案、《政府道德法》）、1974年中期选举75名“水门婴儿”民主党新人，加深了民众对政客的蔑视，并使共和党右转。", "exp_en": "Watergate was the defining political scandal of the era of limits, proving that presidential abuse of power could be checked — at the cost of lasting cynicism about government.", "exp_zh": "水门事件是“有限时代”的标志性政治丑闻，证明总统滥权可以被制约——代价是对政府持久的犬儒主义。", "page": 947}, {"id": "p8-051", "period": 8, "topic_en": "Proposition 13 and the Tax Revolt", "topic_zh": "13号提案与减税运动", "year": 1978, "year_text": "1978", "who": ["Howard Jarvis"], "who_zh": ["霍华德·贾维斯"], "what_en": "In 1978 Howard Jarvis, a conservative anti–New Dealer, proposed California's Proposition 13, an initiative rolling back property taxes, capping future increases, and requiring a two-thirds legislative majority for all tax measures; despite opposition from virtually the entire state leadership, Californians voted overwhelmingly for it.", "what_zh": "1978年，反新政的保守派霍华德·贾维斯提出加州13号提案：回滚房产税、限制未来涨幅、要求所有税收法案须获议会三分之二多数；尽管几乎整个州领导层（两党）一致反对，加州选民仍压倒性通过。", "cause_en": "Inflation drove property values upward and property taxes skyrocketed, hitting suburban homeowners and retirees on fixed incomes with suddenly unaffordable tax bills.", "cause_zh": "通胀推高房价、房产税飙升，让郊区房主和靠固定收入的退休者突然面临难以承受的税单。", "sig_en": "Proposition 13 hobbled public spending — per capita California school funding plunged from the top tier to near the bottom — inspired tax revolts across the country, and helped conservatives define an enduring issue: low taxes.", "sig_zh": "13号提案束缚了公共开支——加州人均学校经费从全国前列跌至接近垫底——在全国引发减税运动，帮助保守派确立了“低税收”这一持久议题。", "exp_en": "Proposition 13 was the grassroots launch of the 1970s tax revolt, converting suburban economic anxiety into a national conservative movement against government spending.", "exp_zh": "13号提案是1970年代减税运动的草根起点，把郊区居民的经济焦虑转化成了全国性的反政府开支保守运动。", "page": 947}, {"id": "p8-052", "period": 8, "topic_en": "Jimmy Carter Elected President", "topic_zh": "吉米·卡特当选总统", "year": 1976, "year_text": "1976", "who": ["Jimmy Carter", "Gerald Ford"], "who_zh": ["吉米·卡特", "杰拉尔德·福特"], "what_en": "James Earl Carter — a naval officer, peanut farmer, and former Georgia governor — emerged to win the 1976 Democratic nomination and defeated Gerald Ford with 50 percent of the popular vote to Ford's 48 percent, trading on Watergate and his Washington-outsider image with the promise 'I will never lie to you.'", "what_zh": "曾任海军军官、花生农场主和佐治亚州州长的吉米·卡特脱颖而出，赢得1976年民主党提名，以50%对48%的普选票击败福特，靠的是水门事件红利和“华盛顿局外人”形象，以及“我永远不会对你们撒谎”的承诺。", "cause_en": "Watergate had discredited the Republicans, and Ford's 'full, free, and absolute' pardon of Nixon was decidedly unpopular, likely costing him enough votes in key states to swing the election.", "cause_zh": "水门事件让共和党信誉扫地，福特对尼克松“完全、自由、绝对”的赦免极不得人心，很可能在关键州丢掉了足以改变选举结果的选票。", "sig_en": "The outsider strategy briefly restored trust — Carter walked to the White House and gave fireside chats in a cardigan — but his inexperience, chilly relations with Congress, and inability to solve stagflation defined a troubled presidency.", "sig_zh": "局外人策略一度重建信任——卡特步行前往白宫、穿着开衫发表炉边谈话——但他的经验不足、与国会关系冷淡以及无法解决滞胀，注定了他多舛的总统任期。", "exp_en": "Carter's 1976 victory was less a liberal triumph than a moral referendum on Watergate, showing how scandal had made outsider status the most valuable political asset.", "exp_zh": "卡特1976年的胜利与其说是自由派的凯旋，不如说是对水门的道德公投，表明丑闻已让“局外人”身份成为最有价值的政治资产。", "page": 949}, {"id": "p8-053", "period": 8, "topic_en": "Bakke v. University of California", "topic_zh": "巴克诉加州大学案", "year": 1978, "year_text": "1978", "who": ["Allan Bakke"], "who_zh": ["艾伦·巴克"], "what_en": "In 1978 Allan Bakke, a white man, sued the UC Davis Medical School for rejecting him in favor of less-qualified minority candidates; the Supreme Court struck down the school's quota system — 16 of 100 places set aside for 'disadvantaged' students — ordered Bakke admitted, but indicated that flexible affirmative action considering race among other factors would pass constitutional muster.", "what_zh": "1978年，白人艾伦·巴克起诉加州大学戴维斯分校医学院，称其录取了条件不如他的少数族裔考生；最高法院推翻了该校的配额制（100个名额中16个预留给“弱势”学生），命令录取巴克，但同时表示将种族作为综合因素之一的灵活平权措施合宪。", "cause_en": "By the early 1970s affirmative action had been refined into hiring and enrollment goals, recruitment programs, and set-asides; many whites felt the deck was stacked against them and charged 'reverse discrimination.'", "cause_zh": "到1970年代初，平权行动已发展为雇佣和招生目标、特别招募培训及预留名额；许多白人感到规则对自己不利，指责这是“逆向歧视”。", "sig_en": "Bakke thus upheld affirmative action but, by rejecting a quota system, also called it into question; future court rulings and state referenda, such as California's Proposition 209 (1996), would further limit its scope.", "sig_zh": "巴克案既维持了平权行动，又因否定配额制而对其提出质疑；此后的法院判决和州公投（如加州1996年209号提案）进一步限制了其范围。", "exp_en": "Bakke drew the constitutional line on affirmative action — no rigid quotas, but race-conscious remedies permitted — a compromise that kept the controversy alive for decades.", "exp_zh": "巴克案为平权行动划定了宪法界线——不许硬性配额，但允许考虑种族的补救措施——这一妥协让争议延续了数十年。", "page": 951, "img": {"file": "img:f2_1718", "credit": "图源：Henretta《America's History》第8版 p.951"}}, {"id": "p8-054", "period": 8, "topic_en": "The Equal Rights Amendment and STOP ERA", "topic_zh": "平等权利修正案与STOP ERA运动", "year": 1972, "year_text": "1972", "who": ["Phyllis Schlafly"], "who_zh": ["菲利斯·施拉弗利"], "what_en": "Congress adopted the Equal Rights Amendment in 1972 — 'Equality of rights under the law shall not be denied or abridged by the United States or any State on the basis of sex' — and within two years 34 of the necessary 38 states ratified; but Phyllis Schlafly's organization STOP ERA (founded 1972) mobilized thousands of women against it, and the ERA was never ratified despite a congressional deadline extension to June 30, 1982.", "what_zh": "国会1972年通过了平等权利修正案——“法律上的平等权利不得因性别被剥夺或削减”——两年内38个所需州中有34个批准；但菲利斯·施拉弗利的STOP ERA组织（成立于1972年）动员数千女性反对，尽管国会把截止期延长至1982年6月30日，修正案最终未能通过。", "cause_en": "Schlafly, a lawyer active in conservative causes, proclaimed the ERA would create an unnatural 'unisex society' — women drafted into the army, single-sex toilets eliminated, abortion never prohibited — a message that resonated with those troubled by rapid social change.", "cause_zh": "长期活跃于保守派事业的律师施拉弗利宣称，修正案会制造不自然的“无性别社会”——女性被征兵、单性别厕所被取消、堕胎永远无法被禁止——这一信息在对社会剧变不安的人群中引起共鸣。", "sig_en": "The ERA's defeat marked the limits of 1970s feminism and demonstrated the rising power of organized conservative grassroots activism, foreshadowing the New Right's cultural campaigns.", "sig_zh": "修正案的失败标志着1970年代女性主义的限度，也显示了保守派草根组织力量的崛起，预示了新右派的文化战争。", "exp_en": "STOP ERA showed that a well-organized conservative women's movement could defeat liberal feminism's central legislative goal on its own terms — the defense of traditional womanhood.", "exp_zh": "STOP ERA表明，一个组织良好的保守派妇女运动能以捍卫传统女性角色为旗号，击败自由派女性主义的核心立法目标。", "src": {"text": "The laws of every one of the 50 states now require the husband to support his wife and children — and to provide a home for them to live in. In other words, the law protects a woman's right to be a full-time wife and mother.", "attr": "Phyllis Schlafly, The Phyllis Schlafly Report, November 1972"}, "page": 952, "img": {"file": "img:f2_1720", "credit": "图源：Henretta《America's History》第8版 p.952"}}, {"id": "p8-055", "period": 8, "topic_en": "Roe v. Wade", "topic_zh": "罗诉韦德案", "year": 1973, "year_text": "1973", "who": ["Supreme Court"], "who_zh": ["最高法院"], "what_en": "In the 1973 landmark decision Roe v. Wade, the Burger Court nullified a Texas law prohibiting abortion under any circumstances and laid out a national standard: abortions performed during the first trimester were protected by the right of privacy, transforming a traditionally state-regulated policy into a national, constitutionally protected right.", "what_zh": "1973年里程碑判决罗诉韦德案中，伯格法院宣布得克萨斯州全面禁止堕胎的法律无效，并确立全国标准：怀孕前三个月的堕胎受隐私权保护，将一项传统上由州管理的政策变为全国性的宪法权利。", "cause_en": "The Court had first recognized a constitutional 'right of privacy' in Griswold v. Connecticut (1965) and gradually expanded it through the late 1960s and early 1970s; women's advocates, stalled in state legislatures, turned to the courts.", "cause_zh": "最高法院1965年在格里斯沃尔德诉康涅狄格案中首次承认宪法“隐私权”，并在60年代末70年代初逐步扩大；妇女权益倡导者在州议会进展缓慢后转向法院。", "sig_en": "For the women's movement Roe was a triumph; for evangelical Christians, Catholics, and conservatives it was a bitter pill that polarized the public, mobilized the religious right, and launched a campaign against the decision that continues today.", "sig_zh": "对妇女运动而言罗案是胜利；对福音派、天主教徒和保守派则是苦果——它激化了公众分裂，动员了宗教右翼，引发了延续至今的反罗案运动。", "exp_en": "Roe extended the Warren Court's privacy doctrine to abortion and became the single most divisive Supreme Court decision of the late twentieth century.", "exp_zh": "罗案把沃伦法院的隐私权学说扩展到堕胎，成为二十世纪后期最具分裂性的最高法院判决。", "page": 956, "img": {"file": "img:f2_1729", "credit": "图源：Henretta《America's History》第8版 p.956"}}];